const $=(sel,root=document)=>root.querySelector(sel);
const $$=(sel,root=document)=>Array.from(root.querySelectorAll(sel));
const uid=()=>globalThis.crypto?.randomUUID?.()||('id'+Date.now().toString(36)+Math.random().toString(36).slice(2));
const now=()=>new Date().toISOString();
const day=(date=new Date())=>{let d=new Date(date);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
const localDate=(s)=>new Date(`${s}T12:00:00`);
const dateFmt=(v,opts={month:'short',day:'numeric'})=>{if(!v)return '—';let d=/^\d{4}-\d\d-\d\d$/.test(v)?localDate(v):new Date(v);return Number.isNaN(d.getTime())?'—':d.toLocaleDateString('en-GB',opts)};
const dayOfWeek=(date=new Date())=>{let n=new Date(date).getDay();return (n+6)%7};
const weekStart=(date=new Date())=>{let d=new Date(date);d.setHours(0,0,0,0);d.setDate(d.getDate()-dayOfWeek(d));return d};
const mondayKey=(date)=>day(weekStart(date));
const addDays=(base,offset)=>{let d=new Date(base);d.setDate(d.getDate()+offset);return day(d)};
const e=(val)=>String(val??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const f=(v,d=1)=>Number.isFinite(Number(v))?Number(v).toLocaleString('en-GB',{maximumFractionDigits:d}):'0';
const clamp=(n,a,b)=>Math.min(b,Math.max(a,n));
const num=(v,def=0)=>Number.isFinite(Number(v))?Number(v):def;
const parseNum=(v)=>{if(v===''||v==null)return null;const x=Number(v);return Number.isFinite(x)?x:null};
const sum=(arr,fn=x=>x)=>arr.reduce((s,x)=>s+num(fn(x)),0);
const avg=(arr)=>arr.length?sum(arr)/arr.length:0;
const label=(s)=>String(s||'').replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
const cap=(s)=>String(s||'').charAt(0).toUpperCase()+String(s||'').slice(1);
const limit=(s,n=70)=>String(s||'').length>n?String(s).slice(0,n-1)+'…':String(s||'');
