const NAV=[['home','⌂','Dashboard'],['workout','◈','Train'],['programs','▦','Programs'],['exercises','◇','Exercises'],['progress','◉','Body'],['analytics','▥','Analytics'],['nutrition','◌','Nutrition'],['cardio','↗','Cardio'],['sleep','☾','Sleep'],['settings','⚙','Settings']];
const defaultState=()=>({schemaVersion:1,settings:{days:4,scheduleMode:'flex',environment:'gym',experience:'beginner',gymEquipment:['Bodyweight','Dumbbells','Barbell','Bench','Cable Machine','Pull-Up Bar','Dip Bars','Leg Press','Leg Curl Machine','Wall'],homeEquipment:['Bodyweight','Dumbbells','Bench','Wall'],selectedProgramId:null,pointer:0,targets:{calories:2400,protein:150},restSeconds:90},exercises:[],favorites:[],programs:[],workouts:[],activeWorkout:null,bodyRecords:[],goals:[],foodsCustom:[],foodFavorites:[],savedMeals:[],foodLogs:[],cardioSessions:[],activeCardio:null,sleepRecords:[]});
let state=defaultState();let db=null,persistent=true,saveTimer=null,screen='home',modal=null,view={},intervalId=null,gpsWatch=null,toastTimer=null;
const allExercises=()=>[...EXERCISES,...state.exercises];
const exercise=(id)=>allExercises().find(x=>x.id===id)||{id,name:'Deleted exercise',primary:'Other',secondary:'',equipment:'Bodyweight',kind:'strength',track:'weight'};
const allFoods=()=>[...FOODS,...state.foodsCustom];
const food=(id)=>allFoods().find(x=>x.id===id)||{id,name:'Deleted food',kcal:0,protein:0,fat:0,carbs:0,unit:'g',serving:100};
const asDate=(v)=>v||day();
const lastWorkout=()=>[...state.workouts].sort((a,b)=>new Date(b.finishedAt)-new Date(a.finishedAt))[0];
const doneSets=(w)=>w.exercises.flatMap(x=>x.sets.filter(s=>s.complete&&!s.skipped).map(s=>({...s,exerciseId:x.exerciseId}))) ;
const validSets=(w)=>w.exercises.reduce((n,x)=>n+x.sets.filter(s=>s.complete&&!s.skipped).length,0);
const volume=(w)=>sum(doneSets(w).filter(s=>exercise(s.exerciseId).track==='weight'),s=>Math.max(0,num(s.reps))*Math.max(0,num(s.weight)));
const durationFmt=(sec)=>{sec=Math.max(0,Math.round(sec));return sec>=3600?`${Math.floor(sec/3600)}h ${Math.floor(sec%3600/60)}m`:`${Math.floor(sec/60)}m ${sec%60}s`};
const clockFmt=(sec)=>`${Math.floor(Math.max(0,sec)/60).toString().padStart(2,'0')}:${Math.floor(Math.max(0,sec)%60).toString().padStart(2,'0')}`;
const weekWorkouts=(start=weekStart())=>state.workouts.filter(w=>mondayKey(w.finishedAt)===day(start));
const groupSets=()=>{let obj={};state.workouts.forEach(w=>w.exercises.forEach(x=>{const ex=exercise(x.exerciseId),n=x.sets.filter(s=>s.complete&&!s.skipped).length;obj[ex.primary]=(obj[ex.primary]||0)+n}));return obj};
const round=(v,d=1)=>Number(num(v).toFixed(d));
function derivePRs(){let prs=[],tops={};const workouts=[...state.workouts].sort((a,b)=>new Date(a.finishedAt)-new Date(b.finishedAt));workouts.forEach(w=>w.exercises.forEach(x=>x.sets.forEach(s=>{if(!s.complete||s.skipped)return;const ex=exercise(x.exerciseId),weight=num(s.weight),reps=num(s.reps),time=num(s.durationSec);let metrics=[];if(ex.track==='weight'){if(reps>0&&weight>0){metrics=[['weight',weight],['e1rm',weight*(1+reps/30)],['reps@'+weight,reps]]}}else if(ex.track==='time')metrics=[['time',time]];else if(ex.track==='assisted')metrics=[['assistance',-num(s.assisted)],['reps',reps]];else metrics=[['reps',reps]];metrics.forEach(([metric,val])=>{if(val<=0&&metric!=='assistance')return;let key=x.exerciseId+'|'+metric;if(tops[key]===undefined||val>tops[key]){const prev=tops[key];tops[key]=val;if(prev!==undefined)prs.push({id:w.id+'-'+s.id+'-'+metric,exerciseId:x.exerciseId,metric,value:metric==='assistance'?-val:val,date:w.finishedAt,workoutId:w.id})}})})));return prs.reverse()}
const exerciseHistory=(id)=>state.workouts.filter(w=>w.exercises.some(x=>x.exerciseId===id)).sort((a,b)=>new Date(b.finishedAt)-new Date(a.finishedAt));
const foodMacros=(entry)=>{const item=entry.snapshot||food(entry.foodId),amount=num(entry.amount),u=entry.unit||item.unit;let basis=u==='serving'?amount*num(item.serving,100):amount;return {kcal:round(item.kcal*basis/100),protein:round(item.protein*basis/100),carbs:round(item.carbs*basis/100),fat:round(item.fat*basis/100)}};
const foodDaily=(date=day())=>{const entries=state.foodLogs.filter(x=>x.date===date);return {entries,kcal:sum(entries,x=>foodMacros(x).kcal),protein:sum(entries,x=>foodMacros(x).protein),carbs:sum(entries,x=>foodMacros(x).carbs),fat:sum(entries,x=>foodMacros(x).fat)}};
function newSessionExercise(exId,sets=3,reps=10,rest=90){return {uid:uid(),exerciseId:exId,sets:Math.max(1,num(sets,3)),reps:Math.max(1,num(reps,10)),rest:Math.max(0,num(rest,90))}}
function sessionToActive(pr){let ex=exercise(pr.exerciseId);return {uid:uid(),exerciseId:pr.exerciseId,notes:'',restSec:pr.rest??state.settings.restSeconds,sets:Array.from({length:pr.sets||3},()=>({id:uid(),reps:ex.track==='time'?0:pr.reps||10,weight:0,assisted:0,durationSec:ex.track==='time'?30:0,rpe:'',rir:'',complete:false,skipped:false}))}}
function defaultOptions(select,selected,withBlank=false){return (withBlank?'<option value="">All</option>':'')+select.map(x=>`<option value="${e(x)}" ${String(x)===String(selected)?'selected':''}>${e(x)}</option>`).join('')}
async function openDB(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window))return reject(new Error('IndexedDB unavailable'));const req=indexedDB.open('forge-fitness-db',1);req.onupgradeneeded=()=>req.result.createObjectStore('kv');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function idbGet(key){return new Promise((res,rej)=>{const tx=db.transaction('kv','readonly'),rq=tx.objectStore('kv').get(key);rq.onsuccess=()=>res(rq.result);rq.onerror=()=>rej(rq.error)})}
function idbSet(key,value){return new Promise((res,rej)=>{const tx=db.transaction('kv','readwrite');tx.objectStore('kv').put(value,key);tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}
function save(){if(!persistent)return;clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{try{await idbSet('state',state)}catch(err){persistent=false;toast('Storage failed. Export a backup immediately.','error');render()}},180)}
function update(fn,rerender=true){fn(state);save();if(rerender)render()}
function toast(message,type='success'){let prev=$('.toast');prev?.remove();const n=document.createElement('div');n.className='toast '+(type==='error'?'error':'');n.setAttribute('role','status');n.textContent=message;document.body.append(n);clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.remove(),3700)}
function navigate(page){screen=page;modal=null;view={};window.scrollTo({top:0,behavior:'instant'});render()}
function showModal(html,wide=false){modal={html,wide};renderModal()}
function closeModal(){modal=null;renderModal()}
function renderModal(){let el=$('#modal-root');if(!el)return;el.innerHTML=modal?`<div class="modal-overlay" data-action="overlay"><div class="modal ${modal.wide?'wide':''}" role="dialog" aria-modal="true">${modal.html}</div></div>`:''}
const empty=(icon,title,message,action='')=>`<div class="empty"><div class="empty-icon">${icon}</div><h3>${e(title)}</h3><p>${e(message)}</p>${action}</div>`;
const action=(name,txt,cls='btn',extra='')=>`<button type="button" class="${cls}" data-action="${name}" ${extra}>${txt}</button>`;
const field=(name,text,value='',type='text',extra='')=>`<div class="field"><label for="${e(name)}">${e(text)}</label><input id="${e(name)}" name="${e(name)}" type="${type}" value="${e(value)}" ${extra}></div>`;
const selectField=(name,text,values,selected)=>`<div class="field"><label for="${e(name)}">${e(text)}</label><select id="${e(name)}" name="${e(name)}">${values.map(x=>{let [val,lab]=Array.isArray(x)?x:[x,x];return `<option value="${e(val)}" ${val==selected?'selected':''}>${e(lab)}</option>`}).join('')}</select></div>`;
const textareaField=(name,text,value='')=>`<div class="field"><label for="${e(name)}">${e(text)}</label><textarea id="${e(name)}" name="${e(name)}">${e(value)}</textarea></div>`;
const formButtons=(title='Save')=>`<div class="modal-actions">${action('close-modal','Cancel','btn ghost')}<button class="btn primary" type="submit">${e(title)}</button></div>`;
const formData=(form)=>Object.fromEntries(new FormData(form).entries());
const metric=(name,value,sub='')=>`<div class="card kpi"><div class="metric-label">${e(name)}</div><div class="metric">${value}</div><div class="micro">${sub||'&nbsp;'}</div></div>`;
function sparkSVG(data,color='#ff663d',height=140){const arr=data.map(x=>Number(x)).filter(Number.isFinite);if(!arr.length)return `<div class="empty" style="padding:25px">No data yet</div>`;const w=600,h=height,p=13,mi=Math.min(...arr),ma=Math.max(...arr),rng=ma-mi||1;const pts=arr.map((v,i)=>[(p+i*(w-2*p)/Math.max(1,arr.length-1)),h-p-(v-mi)/rng*(h-2*p)]);const path=pts.map((xy,i)=>(i?'L':'M')+xy.map(v=>v.toFixed(1)).join(' ')).join(' ');const area=path+` L ${pts.at(-1)[0]} ${h-p} L ${pts[0][0]} ${h-p} Z`;return `<div class="line-chart"><svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><line x1="0" y1="${h-p}" x2="${w}" y2="${h-p}" stroke="#3e4047"/><line x1="0" y1="${Math.round(h/2)}" x2="${w}" y2="${Math.round(h/2)}" stroke="#33353b" stroke-dasharray="3,7"/><path d="${area}" fill="${color}" opacity=".12"/><path d="${path}" fill="none" stroke="${color}" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/>${pts.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="3.6" fill="${color}" stroke="#1a1c22" stroke-width="2"/>`).join('')}</svg></div>`}
function bars(data,labels,selectedColor='var(--accent)'){if(!data.length)return '<div class="muted">No data yet</div>';const mx=Math.max(1,...data);return `<div class="mini-chart">${data.map((v,i)=>`<div class="bar-col"><div class="bar" style="height:${Math.max(2,v/mx*82)}%;background:${selectedColor}" title="${e(labels[i])}: ${f(v)}"></div><div class="bar-caption">${e(labels[i])}</div></div>`).join('')}</div>`}
const simpleList=(rows,renderRow)=>rows.map(renderRow).join('');
function layout(){const current=NAV.find(n=>n[0]===screen)||NAV[0];let content;try{content=pages[screen]?.()||homePage()}catch(err){console.error(err);content=`<div class="notice error">This screen encountered an error: ${e(err.message)}. Your saved data has not been deleted.</div>${action('go-home','Dashboard','btn primary')}`}
$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><span class="brand-symbol">F</span><span>FORGE<span class="accent">.</span></span></div><div class="nav-label">Training</div>${NAV.slice(0,4).map(n=>navBtn(n)).join('')}<div class="nav-label">Your data</div>${NAV.slice(4,9).map(n=>navBtn(n)).join('')}<div class="nav-label">App</div>${navBtn(NAV[9])}<div class="sidebar-bottom"><b>PRIVATE BY DESIGN</b><p>Stored on your device. No account, no subscription.</p></div></aside><main class="main"><div class="topbar"><div><div class="eyebrow">FORGE / ${e(current[2].toUpperCase())}</div><div style="font-size:12px;color:var(--muted)">Built for progress, not excuses.</div></div><div class="head-right"><span class="date-pill">${dateFmt(new Date(),{weekday:'short',day:'numeric',month:'short',year:'numeric'})}</span>${action('open-settings','⚙','btn icon')}</div></div>${!persistent?'<div class="notice error"><b>Storage unavailable.</b> Changes may not survive reopening. Use a supported browser and export backups.</div>':''}${content}</main><nav class="bottom-nav">${[NAV[0],NAV[1],NAV[2],NAV[5]].map(n=>navBtn(n,true)).join('')}<button data-action="mobile-more"><span class="nav-icon">☰</span><span>More</span></button></nav></div><div id="modal-root"></div>`;renderModal();refreshTimers()}
function navBtn(n,mobile=false){return `<button class="${mobile?'':'nav-link '}${screen===n[0]?'active':''}" data-action="nav" data-page="${n[0]}" aria-label="${e(n[2])}"><span class="nav-icon">${n[1]}</span><span>${e(n[2])}</span></button>`}
function render(){layout()}
function renderKeep(){const saved=new Map();$$('input:focus,textarea:focus,select:focus').forEach(el=>saved.set(el.name,el.selectionStart));render()}
function refreshTimers(){const w=state.activeWorkout,c=state.activeCardio;if(w){const el=$('#workout-clock');if(el)el.textContent=durationFmt((Date.now()-new Date(w.startedAt).getTime())/1000);const rt=$('#rest-clock');if(rt){let secs=Math.ceil((num(w.restUntil)-Date.now())/1000);rt.textContent=secs>0?clockFmt(secs):'00:00';if(secs<=0&&w.restUntil){w.restUntil=null;save();rt.closest('.rest-area')?.classList.add('hide');if(document.visibilityState==='visible')toast('Rest complete — ready for your next set.')}}}
if(c){let elapsed=Date.now()-new Date(c.startedAt).getTime()-num(c.pauseMs)-(c.pausedAt?Date.now()-new Date(c.pausedAt).getTime():0);const el=$('#cardio-clock');if(el)el.textContent=durationFmt(elapsed/1000);const d=$('#cardio-distance');if(d)d.textContent=f(c.distanceKm,2)+' km'}}
async function init(){try{db=await openDB();const saved=await idbGet('state');if(saved&&saved.schemaVersion===1){state={...defaultState(),...saved,settings:{...defaultState().settings,...saved.settings}}}}catch(err){persistent=false;console.warn('IndexedDB unavailable',err)}if(!state.settings.gymEquipment)state.settings.gymEquipment=defaultState().settings.gymEquipment;if(!state.settings.homeEquipment)state.settings.homeEquipment=defaultState().settings.homeEquipment;render();intervalId=setInterval(refreshTimers,1000);if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});if(state.activeCardio?.gpsEnabled&&!state.activeCardio.pausedAt)startGPS()}
/* Dashboard, programs, exercise library, live training */
const activeProgram=()=>state.programs.find(p=>p.id===state.settings.selectedProgramId)||null;
function nextSession(){const p=activeProgram();if(!p?.sessions?.length)return null;if(state.settings.scheduleMode==='flex')return {program:p,session:p.sessions[(state.settings.pointer||0)%p.sessions.length],index:(state.settings.pointer||0)%p.sessions.length};let wd=dayOfWeek();let assigned=p.sessions.find(s=>num(s.weekday,-1)===wd);if(assigned)return {program:p,session:assigned,index:p.sessions.indexOf(assigned)};for(let i=1;i<=7;i++){const target=(wd+i)%7,ss=p.sessions.find(s=>num(s.weekday,-1)===target);if(ss)return {program:p,session:ss,index:p.sessions.indexOf(ss),inDays:i}}return {program:p,session:p.sessions[0],index:0}}
function sessionName(){const n=nextSession();return n?.session?.name||'Your next session'}
function homePage(){const w=state.activeWorkout,ns=nextSession(),recent=lastWorkout(),current=weekWorkouts(),prs=derivePRs().slice(0,3),target=Math.max(1,state.settings.days),weekDays=['M','T','W','T','F','S','S'],base=weekStart(),weekCount=current.length;const homeRecent=state.workouts.slice().sort((a,b)=>new Date(b.finishedAt)-new Date(a.finishedAt)).slice(0,3);
return `<div class="page-header"><div><div class="eyebrow">YOUR TRAINING HQ</div><h1 class="top-title">OWN YOUR <span class="accent">PROGRESS.</span></h1><p class="subtitle">Your next rep starts here. Every session counts.</p></div>${action('nav','VIEW ANALYTICS ↗','btn ghost','data-page="analytics"')}</div>
<div class="hero"><div><span class="tag orange">${w?'● WORKOUT IN PROGRESS':ns?'UP NEXT • '+e(state.settings.scheduleMode.toUpperCase()):'READY WHEN YOU ARE'}</span><h2>${w?e(w.name):ns?e(ns.session.name):'Your training starts with one session.'}</h2><p>${w?`Session started ${dateFmt(w.startedAt)}. ${validSets(w)} sets logged so far.`:ns?`${e(ns.program.name)} · ${ns.session.exercises.length} exercises · ${ns.inDays?`scheduled in ${ns.inDays} day(s)`:'ready to begin'}`:'Generate a personalized training plan or create your own.'}</p><div class="hero-actions">${w?action('nav','▶ CONTINUE WORKOUT','btn primary','data-page="workout"'):ns?action('start-session','▶ START WORKOUT','btn primary',`data-program="${e(ns.program.id)}" data-session="${e(ns.session.id)}"`):action('nav','✦ CREATE A PROGRAM','btn primary','data-page="programs"')}${action('quick-start','＋ EMPTY SESSION','btn ghost')}</div></div><div class="hero-icon">F.</div></div>
<div class="shortcut-row">${[['workout','◈ Train'],['programs','▦ Plans'],['analytics','▥ Insights'],['progress','◉ Body'],['nutrition','◌ Nutrition'],['cardio','↗ Cardio'],['sleep','☾ Sleep'],['settings','⚙ Settings']].map(([page,name])=>action('nav',name,'shortcut',`data-page="${page}"`)).join('')}</div><div class="grid cols-4">${metric('WORKOUTS THIS WEEK',f(weekCount,0)+` <span>/ ${target}</span>`,weekCount>=target?'Weekly target achieved':'Keep showing up')}${metric('TOTAL WORKOUTS',f(state.workouts.length,0),'Sessions completed')}${metric('WORKING SETS',f(sum(state.workouts,validSets),0),'All-time completed sets')}${metric('PERSONAL RECORDS',f(derivePRs().length,0),'New record events')}</div>
<div class="split" style="margin-top:17px"><div class="card"><div class="card-head"><h3>Weekly consistency</h3><span class="tag ${weekCount>=target?'lime':'orange'}">${Math.min(100,Math.round(weekCount/target*100))}% of goal</span></div><div class="week-dots">${weekDays.map((s,i)=>{let val=day(new Date(base.getFullYear(),base.getMonth(),base.getDate()+i)),did=current.some(w=>day(w.finishedAt)===val);return `<div class="week-dot"><span class="${did?'filled':''}">${did?'✓':dateFmt(val,{day:'numeric'})}</span>${s}</div>`}).join('')}</div><div class="divider"></div><div class="row between"><span class="muted">Your weekly training target</span><b>${weekCount} of ${target} sessions</b></div><div class="progress-track" style="margin-top:10px"><div class="progress-fill" style="width:${Math.min(100,weekCount/target*100)}%"></div></div></div>
<div class="card"><div class="card-head"><h3>Latest session</h3>${action('nav','History ↗','btn small ghost','data-page="workout"')}</div>${recent?`<div class="row between"><div><b>${e(recent.name)}</b><div class="micro" style="margin-top:6px">${dateFmt(recent.finishedAt)} · ${durationFmt(recent.durationSec)}</div></div><span class="badge-box">✓</span></div><div class="divider"></div><div class="row between"><span class="muted">Working sets</span><b>${validSets(recent)}</b></div><div class="row between" style="margin-top:11px"><span class="muted">Weighted volume</span><b>${f(volume(recent),0)} kg</b></div>`:empty('◷','No sessions yet','Your finished workouts appear here.')}</div></div>
<div class="split" style="margin-top:17px"><div class="card"><div class="card-head"><h3>Recent sessions</h3>${action('nav','All history ↗','btn small ghost','data-page="workout"')}</div>${homeRecent.length?homeRecent.map((x,i)=>`<div class="list-item"><div class="row"><div class="badge-box">${i+1}</div><div><div class="main-line">${e(x.name)}</div><div class="sub-line">${dateFmt(x.finishedAt)} · ${validSets(x)} sets · ${durationFmt(x.durationSec)}</div></div></div><span class="tag">${f(volume(x),0)} kg</span></div>`).join(''):empty('◈','Nothing logged yet','Complete your first session to begin building your history.')}</div>
<div class="card"><div class="card-head"><h3>Recent personal records</h3>${action('nav','All PRs ↗','btn small ghost','data-page="analytics"')}</div>${prs.length?prs.map(p=>`<div class="list-item"><div class="row"><div class="badge-box">★</div><div><div class="main-line">${e(exercise(p.exerciseId).name)}</div><div class="sub-line">${e(prLabel(p.metric,p.value))}</div></div></div><span class="micro">${dateFmt(p.date)}</span></div>`).join(''):empty('☆','Your PR board is empty','Your achievements will appear as you repeat exercises and improve.')}</div></div>`}
function prLabel(m,v){if(m==='weight')return `${f(v)} kg max weight`;if(m==='e1rm')return `${f(v)} kg estimated 1RM`;if(m.startsWith('reps@'))return `${f(v,0)} reps at ${m.slice(5)} kg`;if(m==='time')return `${f(v,0)} sec hold`;if(m==='assistance')return `${f(v)} kg assistance`;return `${f(v,0)} repetitions`}
function availableExercises(env){const allowed=state.settings[env==='home'?'homeEquipment':'gymEquipment']||[];return allExercises().filter(x=>allowed.includes(x.equipment)||x.equipment==='Bodyweight')}
function generateProgram(daysCount,duration,env,experience){const eligible=availableExercises(env);const has=id=>eligible.some(x=>x.id===id);const choose=(ids)=>ids.find(has);const split=daysCount>=4?['Upper A','Lower A','Upper B','Lower B']:daysCount===3?['Full Body A','Full Body B','Full Body C']:daysCount===2?['Full Body A','Full Body B']:['Full Body'];const sessions=[];for(let index=0;index<daysCount;index++){let type=split[index%split.length],upper=type.startsWith('Upper'),lower=type.startsWith('Lower'),even=index%2===0;let groups=upper?[['db-bench','barbell-bench','pushup'],['pullup','assisted-pullup','lat-pull','db-row','inverted-row'],['db-ohp','ohp','pike'],['db-row','cable-row','bb-row'],['lateral','facepull'],['db-curl','bb-curl','hammer'],['overhead-tri','tricep-push','dip']]:lower?[['goblet','squat','bw-squat','legpress'],['db-rdl','rdl','glute-bridge'],['lunge','split-squat','bw-squat'],['legcurl','glute-bridge'],['db-calf','calf'],['plank','hollow','dead-bug']]:[['goblet','squat','bw-squat'],['pushup','db-bench','barbell-bench'],['pullup','assisted-pullup','db-row','inverted-row'],['db-rdl','rdl','glute-bridge'],['db-ohp','pike','ohp'],['plank','dead-bug']];if(!even)groups=groups.map(a=>[...a].reverse());const result=[];groups.forEach(g=>{let ex=choose(g);if(ex&&!result.some(x=>x.exerciseId===ex))result.push(newSessionExercise(ex,experience==='advanced'?4:3,experience==='beginner'?10:8,90))});const cali=upper?['pullup','assisted-pullup','pushup','dip','inverted-row']:lower?['glute-bridge','hanging-knee','plank']:['pushup','inverted-row','hollow'];let cal=cali.find(x=>has(x)&&!result.some(a=>a.exerciseId===x));if(cal)result.push(newSessionExercise(cal,2,8,80));let mobility=['hip-flexor','deep-squat','t-spine','hamstring-stretch','shoulder-pass','ankle','cat-cow'].filter(has);mobility.slice(index%2,2+index%2).forEach(ex=>result.push(newSessionExercise(ex,2,exercise(ex).track==='time'?30:10,30)));const maxExercises=Math.max(3,Math.floor((duration-9)/12));const limited=result.slice(0,Math.min(result.length,maxExercises));if(limited.length>2&&!limited.some(x=>exercise(x.exerciseId).kind==='mobility')&&mobility.length)limited[limited.length-1]=newSessionExercise(mobility[0],2,30,30);sessions.push({id:uid(),name:type,weekday:daysCount===4?[0,1,3,4][index]:daysCount===3?[0,2,4][index]:index%7,exercises:limited})}return {id:uid(),name:`${daysCount}-Day ${env==='gym'?'Gym':'Home'} Training`,createdAt:now(),environment:env,description:`${duration}-minute target · ${experience} · Muscle, calisthenics and mobility`,sessions}}
function programsPage(){const selected=state.programs.find(p=>p.id===view.programId);return `<div class="page-header"><div><h1>Training <span class="accent">Programs</span></h1><p class="subtitle">Your plan. Your pace. Built to adapt.</p></div><div class="page-actions">${action('create-program','＋ Manual plan','btn')}${action('generate-program','✦ Generate plan','btn primary')}</div></div>
${selected?`<div class="card" style="margin-bottom:18px"><div class="card-head"><div><h2>${e(selected.name)}</h2><div class="micro">${e(selected.description||'Custom training program')} · ${e(cap(selected.environment))}</div></div>${action('program-back','Close','btn small')}</div><div class="row wrap" style="margin-bottom:14px">${action('program-edit','Edit details','btn small',`data-id="${e(selected.id)}"`)}${action('program-session-add','＋ Add session','btn small primary',`data-id="${e(selected.id)}"`)}${action('program-activate',activeProgram()?.id===selected.id?'✓ Active program':'Set active','btn small',`data-id="${e(selected.id)}"`)}${action('program-duplicate','Duplicate','btn small',`data-id="${e(selected.id)}"`)}${action('program-delete','Delete','btn small danger',`data-id="${e(selected.id)}"`)}</div>${selected.sessions.length?selected.sessions.map((ss,i)=>`<div class="session-block"><div class="session-top"><div><b>${e(ss.name)}</b><div class="micro">${ss.exercises.length} exercises · ${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][num(ss.weekday)]}</div></div><div class="row wrap">${action('start-session','▶','btn small primary',`data-program="${e(selected.id)}" data-session="${e(ss.id)}"`)}${action('session-edit','Edit','btn small',`data-program="${e(selected.id)}" data-session="${e(ss.id)}"`)}${action('session-delete','✕','btn small danger',`data-program="${e(selected.id)}" data-session="${e(ss.id)}"`)}</div></div>${ss.exercises.length?ss.exercises.map(x=>`<div class="list-item"><div><div class="main-line">${e(exercise(x.exerciseId).name)}</div><div class="sub-line">${e(exercise(x.exerciseId).primary)} · ${x.sets} sets × ${x.reps} ${exercise(x.exerciseId).track==='time'?'seconds':'reps'} · ${x.rest}s rest</div></div></div>`).join(''):empty('＋','No exercises','Edit this session to add exercises.')}</div>`).join(''):empty('▦','No sessions yet','Add a session to build this program.')}</div>`:''}
${!state.programs.length?empty('▦','No training plans yet','Generate a personalized program in seconds, or design your own.',action('generate-program','✦ Generate your first plan','btn primary')):`<div class="grid cols-2">${state.programs.map(p=>`<div class="program-card ${p.id===state.settings.selectedProgramId?'active':''}"><div class="row between"><span class="tag ${p.id===state.settings.selectedProgramId?'orange':''}">${p.id===state.settings.selectedProgramId?'● ACTIVE':'SAVED PROGRAM'}</span><span class="micro">${dateFmt(p.createdAt)}</span></div><h2 style="margin-top:17px">${e(p.name)}</h2><p class="micro">${e(p.description||'Your own training plan')}</p><div class="row wrap" style="margin:18px 0"><span class="tag">${p.sessions.length} sessions</span><span class="tag">${cap(p.environment)}</span><span class="tag">${sum(p.sessions,x=>x.exercises.length)} exercises</span></div><div class="row">${action('program-view','View plan ↗','btn primary',`data-id="${e(p.id)}"`)}${p.id!==state.settings.selectedProgramId?action('program-activate','Activate','btn',`data-id="${e(p.id)}"`):''}</div></div>`).join('')}</div>`}`}
function exercisesPage(){const q=String(view.search||'').toLowerCase(),kind=view.kind||'all',equipment=view.equipment||'all',all=allExercises().filter(x=>(x.name+' '+x.primary+' '+x.secondary).toLowerCase().includes(q)&&(kind==='all'||x.kind===kind)&&(equipment==='all'||x.equipment===equipment)&&(view.favoritesOnly?state.favorites.includes(x.id):true));return `<div class="page-header"><div><h1>Exercise <span class="accent">Library</span></h1><p class="subtitle">A full training toolbox, even when you're offline.</p></div>${action('exercise-create','＋ Custom exercise','btn primary')}</div><div class="card"><div class="filters"><div class="field" style="flex:2;min-width:190px"><label>Search exercises</label><input id="exercise-search" placeholder="Search by name or muscle…" value="${e(view.search||'')}"></div><div class="field"><label>Type</label><select id="exercise-kind">${[['all','All types'],['strength','Strength'],['calisthenics','Calisthenics'],['mobility','Mobility']].map(([v,t])=>`<option value="${v}" ${kind===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>Equipment</label><select id="exercise-equipment"><option value="all">All equipment</option>${defaultOptions(EQUIPMENT,equipment)}</select></div></div><div class="row between" style="margin-bottom:10px"><span class="micro">${all.length} exercises</span>${action('favorites-toggle',view.favoritesOnly?'★ Favorites only':'☆ Show favorites','btn small')}</div>${all.length?`<div class="grid cols-2">${all.map(x=>`<div class="card soft"><div class="row between"><span class="tag ${x.kind==='mobility'?'lime':x.kind==='calisthenics'?'orange':''}">${e(cap(x.kind))}</span>${action('exercise-favorite',state.favorites.includes(x.id)?'★':'☆','tiny-btn',`data-id="${e(x.id)}" aria-label="Favorite ${e(x.name)}"`)}</div><h3 style="margin:13px 0 6px">${e(x.name)}</h3><div class="micro">${e(x.primary)} ${x.secondary?'· '+e(x.secondary):''} · ${e(x.equipment)}</div><div class="micro" style="margin:11px 0">${e(x.instructions)}</div><div class="row between"><span class="tag">${e(x.difficulty)}</span><div class="row">${action('exercise-details','History','btn small',`data-id="${e(x.id)}"`)}${x.custom?action('exercise-edit','Edit','btn small',`data-id="${e(x.id)}"`):''}</div></div></div>`).join('')}</div>`:empty('◇','No matching exercises','Try another filter or add a custom exercise.')}</div>`}
function workoutPage(){if(state.activeWorkout)return liveWorkoutPage();const history=state.workouts.slice().sort((a,b)=>new Date(b.finishedAt)-new Date(a.finishedAt));return `<div class="page-header"><div><h1>Train <span class="accent">Harder.</span></h1><p class="subtitle">One focused session at a time.</p></div><div class="page-actions">${action('quick-start','＋ Empty workout','btn')}${nextSession()?action('start-next','▶ Start next session','btn primary'):action('nav','Choose program','btn primary','data-page="programs"')}</div></div><div class="card" style="margin-bottom:18px"><div class="card-head"><h3>Workout history</h3><span class="tag">${history.length} sessions</span></div>${history.length?history.map(w=>`<div class="list-item"><div class="row"><div class="badge-box">◈</div><div><div class="main-line">${e(w.name)}</div><div class="sub-line">${dateFmt(w.finishedAt,{month:'short',day:'numeric',year:'numeric'})} · ${validSets(w)} sets · ${durationFmt(w.durationSec)}</div></div></div><div class="row"><span class="tag">${f(volume(w),0)} kg</span>${action('workout-detail','View','btn small',`data-id="${e(w.id)}"`)}</div></div>`).join(''):empty('◈','No completed workouts','Starting and finishing a workout creates your first permanent training record.')}</div>`}
function liveWorkoutPage(){const w=state.activeWorkout;return `<div class="page-header"><div><div class="eyebrow">● LIVE SESSION</div><h1>${e(w.name)}</h1><p class="subtitle">${dateFmt(w.startedAt)} · Your progress saves as you log.</p></div>${action('workout-rename','✎ Rename','btn small')}</div>
<div class="workout-sticky"><div class="row"><span style="font-size:22px;color:var(--accent)">◈</span><div><div class="micro">Elapsed time</div><b id="workout-clock">${durationFmt((Date.now()-new Date(w.startedAt).getTime())/1000)}</b></div></div><div class="row"><span class="tag lime">${validSets(w)} sets</span>${action('workout-abandon','Discard','btn small danger')}${action('workout-finish','FINISH ↗','btn primary')}</div></div>
${w.restUntil&&w.restUntil>Date.now()?`<div class="card rest-area" style="margin-bottom:13px;border-color:#687441"><div class="row between"><div><div class="metric-label">REST TIMER</div><div class="rest-timer" id="rest-clock">${clockFmt(Math.ceil((w.restUntil-Date.now())/1000))}</div></div><div class="row">${action('rest-add','＋ 15s','btn small')}${action('rest-skip','Skip rest','btn small')}</div></div></div>`:''}
${w.exercises.map((x,i)=>{const ex=exercise(x.exerciseId),previous=exerciseHistory(ex.id)[0],lastX=previous?.exercises.find(a=>a.exerciseId===ex.id),historyText=lastX?lastX.sets.filter(s=>s.complete&&!s.skipped).map(s=>ex.track==='time'?`${s.durationSec||0}s`:ex.track==='weight'?`${s.weight||0}kg × ${s.reps||0}`:`${s.reps||0} reps`).join(' / '):'First recorded session';return `<div class="card" style="margin-bottom:13px"><div class="row between wrap"><div><span class="tag ${ex.kind==='mobility'?'lime':ex.kind==='calisthenics'?'orange':''}">${e(ex.primary)} · ${e(ex.kind)}</span><h3 style="font-size:18px;margin:9px 0 3px">${i+1}. ${e(ex.name)}</h3><div class="micro">Previous: ${e(historyText||'No sets logged')}</div></div><div class="row">${action('workout-ex-move','↑','tiny-btn',`data-ex="${e(x.uid)}" data-direction="-1"`)}${action('workout-ex-move','↓','tiny-btn',`data-ex="${e(x.uid)}" data-direction="1"`)}${action('workout-ex-remove','×','tiny-btn',`data-ex="${e(x.uid)}"`)}</div></div>
<div class="divider"></div><div style="overflow-x:auto"><table class="set-table"><thead><tr><th style="width:35px">Set</th>${ex.track==='time'?'<th>Seconds</th>':`<th>Reps</th>${ex.track==='weight'?'<th>Kg</th>':''}${ex.track==='assisted'?'<th>Assist kg</th>':''}`}<th>RPE</th><th>RIR</th><th style="width:39px">Done</th><th style="width:33px">Skip</th><th style="width:28px"></th></tr></thead><tbody>${x.sets.map((s,j)=>`<tr class="${s.complete?'done':s.skipped?'skipped':''}"><td>${j+1}</td>${ex.track==='time'?`<td>${setInput(x.uid,s.id,'durationSec',s.durationSec,'number','min="0" step="1"')}</td>`:`<td>${setInput(x.uid,s.id,'reps',s.reps,'number','min="0" step="1"')}</td>${ex.track==='weight'?`<td>${setInput(x.uid,s.id,'weight',s.weight,'number','min="0" step="0.5"')}</td>`:''}${ex.track==='assisted'?`<td>${setInput(x.uid,s.id,'assisted',s.assisted,'number','min="0" step="0.5"')}</td>`:''}`}<td>${setInput(x.uid,s.id,'rpe',s.rpe,'number','min="1" max="10" step="0.5"')}</td><td>${setInput(x.uid,s.id,'rir',s.rir,'number','min="0" max="10" step="1"')}</td><td><button class="tiny-btn" data-action="set-done" data-ex="${e(x.uid)}" data-set="${e(s.id)}" title="Mark complete">${s.complete?'✓':'○'}</button></td><td><button class="tiny-btn" data-action="set-skip" data-ex="${e(x.uid)}" data-set="${e(s.id)}" title="Skip set">${s.skipped?'↩':'–'}</button></td><td><button class="tiny-btn" data-action="set-remove" data-ex="${e(x.uid)}" data-set="${e(s.id)}" title="Remove set">×</button></td></tr>`).join('')}</tbody></table></div><div class="row between wrap" style="margin-top:12px"><div class="row"><span class="micro">Rest</span><input type="number" min="0" max="600" step="15" class="control" style="width:77px;padding:7px" data-field="restSec" data-ex="${e(x.uid)}" value="${e(x.restSec)}" aria-label="Rest seconds"><span class="micro">sec</span></div>${action('set-add','＋ Add set','btn small',`data-ex="${e(x.uid)}"`)}</div><div class="exercise-note"><input placeholder="Notes: form, tempo, adjustments…" value="${e(x.notes)}" data-field="notes" data-ex="${e(x.uid)}" aria-label="Exercise notes"></div></div>`}).join('')}
${action('workout-add-exercise','＋ ADD EXERCISE','add-row')}<div class="row wrap" style="justify-content:center;margin-top:18px">${action('workout-finish','✓ FINISH WORKOUT','btn primary')}${action('workout-abandon','Discard session','btn danger')}</div>`}
function setInput(ex,set,field,val,type='number',extra=''){return `<input type="${type}" data-ex="${e(ex)}" data-set="${e(set)}" data-field="${e(field)}" value="${e(val??'')}" ${extra}>`}
/* Body, analysis, nutrition, cardio, sleep and settings */
function progressPage(){const all=[...state.bodyRecords].sort((a,b)=>a.date.localeCompare(b.date));const latest=all.at(-1),first=all[0],metricKey=view.bodyMetric||'weight',allowed=['weight','bodyFat','chest','waist','arms','shoulders','hips','thighs'];const data=all.filter(x=>Number.isFinite(Number(x[metricKey]))&&x[metricKey]!==''&&x[metricKey]!=null);const cur=data.at(-1);const delta=data.length>1?num(data.at(-1)[metricKey])-num(data.at(-2)[metricKey]):null;return `<div class="page-header"><div><h1>Body <span class="accent">Progress</span></h1><p class="subtitle">Measure the change. Celebrate the process.</p></div>${action('body-add','＋ Add measurement','btn primary')}</div><div class="grid cols-3">${metric('LATEST WEIGHT',latest?.weight!=null?f(latest.weight)+' <span>kg</span>':'—','Latest recorded weight')}${metric('BODY FAT',latest?.bodyFat!=null?f(latest.bodyFat)+' <span>% est.</span>':'—','Self-reported estimate')}${metric('CHECK-INS',all.length,'Measurement entries')}</div><div class="card" style="margin-top:17px"><div class="card-head"><h3>Measurement trend</h3><div class="field"><select id="body-metric">${allowed.map(x=>`<option value="${x}" ${metricKey===x?'selected':''}>${label(x)}</option>`).join('')}</select></div></div>${data.length?sparkSVG(data.map(x=>x[metricKey])):empty('◉','No readings for this metric','Add measurements to display your trend.')}<div class="row between"><span class="micro">${data.length?dateFmt(data[0].date):'—'} to ${data.length?dateFmt(data.at(-1).date):'—'}</span><span class="tag ${delta!=null?'orange':''}">${delta!=null?(delta>0?'+':'')+f(delta)+' '+(metricKey==='bodyFat'?'pp':metricKey==='weight'?'kg':'cm')+' since last entry':'Need 2 entries for changes'}</span></div></div>
<div class="card" style="margin-top:17px"><div class="card-head"><h3>Measurement history</h3><span class="tag">${all.length} records</span></div>${all.length?[...all].reverse().map(x=>`<div class="list-item"><div><div class="main-line">${dateFmt(x.date,{month:'short',day:'numeric',year:'numeric'})}</div><div class="sub-line">${x.weight!==''&&x.weight!=null?f(x.weight)+' kg':''}${x.bodyFat!==''&&x.bodyFat!=null?' · '+f(x.bodyFat)+'% body fat (estimated)':''}${['chest','waist','arms','shoulders','hips','thighs'].filter(k=>x[k]!==''&&x[k]!=null).map(k=>` · ${label(k)} ${f(x[k])} cm`).join('')}</div></div><div class="row">${action('body-edit','Edit','btn small',`data-id="${e(x.id)}"`)}${action('body-delete','×','btn small danger',`data-id="${e(x.id)}"`)}</div></div>`).join(''):empty('◉','No measurements','Your measurements are private and stored only on this device.')}</div>`}
function exerciseSeries(id,range='all'){const start=range==='30'?Date.now()-30*864e5:range==='90'?Date.now()-90*864e5:0;return exerciseHistory(id).filter(w=>new Date(w.finishedAt).getTime()>=start).reverse().map(w=>{const x=w.exercises.find(x=>x.exerciseId===id);const sets=x.sets.filter(s=>s.complete&&!s.skipped);const t=exercise(id).track;return {date:w.finishedAt,value:t==='weight'?Math.max(0,...sets.map(s=>num(s.weight)*(1+num(s.reps)/30))):t==='time'?Math.max(0,...sets.map(s=>num(s.durationSec))):Math.max(0,...sets.map(s=>num(s.reps)))}}).filter(x=>x.value>0)}
function goalCurrent(g){if(g.metric==='workouts')return state.workouts.length;if(g.metric==='cardio')return sum(state.cardioSessions,x=>x.distanceKm);if(g.metric==='reps')return Math.max(0,...state.workouts.flatMap(w=>w.exercises.filter(x=>x.exerciseId===g.exerciseId).flatMap(x=>x.sets.filter(s=>s.complete&&!s.skipped).map(s=>num(s.reps)))));const arr=exerciseSeries(g.exerciseId);if(g.metric==='e1rm')return Math.max(0,...arr.map(x=>x.value));if(g.metric==='weight')return Math.max(0,...state.workouts.flatMap(w=>w.exercises.filter(x=>x.exerciseId===g.exerciseId).flatMap(x=>x.sets.filter(s=>s.complete&&!s.skipped).map(s=>num(s.weight)))));return 0}
function analyticsPage(){let range=view.range||'30',exId=view.exerciseId||EXERCISES[0].id,trend=exerciseSeries(exId,range),prs=derivePRs(),thisWeek=weekWorkouts(),lastWeek=weekWorkouts(new Date(weekStart().getTime()-7*864e5)),counts=groupSets();const periodDays=range==='all'?36500:num(range);const cutoff=Date.now()-periodDays*864e5;const filtered=state.workouts.filter(w=>new Date(w.finishedAt).getTime()>=cutoff);const weekLabels=Array.from({length:8},(_,i)=>{let d=new Date(weekStart().getTime()-(7-i)*7*864e5);return dateFmt(d,{month:'short',day:'numeric'})});const weekCounts=Array.from({length:8},(_,i)=>{let d=new Date(weekStart().getTime()-(7-i)*7*864e5);return weekWorkouts(d).length});const weekVolume=Array.from({length:8},(_,i)=>{let d=new Date(weekStart().getTime()-(7-i)*7*864e5);return sum(weekWorkouts(d),volume)});const recommendations=[];const byEx=[...new Set(state.workouts.flatMap(w=>w.exercises.map(x=>x.exerciseId)))];byEx.slice(0,8).forEach(id=>{let hist=exerciseHistory(id).slice(0,2);if(hist.length<2)return;let item=exercise(id);if(item.track!=='weight')return;let ex=hist[0].exercises.find(x=>x.exerciseId===id),prev=hist[1].exercises.find(x=>x.exerciseId===id);let active=ex.sets.filter(s=>s.complete&&!s.skipped),older=prev.sets.filter(s=>s.complete&&!s.skipped);if(!active.length||!older.length)return;let curVal=Math.max(...active.map(s=>num(s.weight)*(1+num(s.reps)/30))),prevVal=Math.max(...older.map(s=>num(s.weight)*(1+num(s.reps)/30)));let repsGood=active.length>=3&&active.every(s=>num(s.reps)>=10&&(s.rpe===''||num(s.rpe)<=8));recommendations.push(`${item.name}: ${repsGood?'All logged working sets reached 10+ reps'+(active.some(s=>s.rpe!=='' )?' with moderate effort':'')+'. Consider a small 1–2.5 kg increase next time if form stays sound.':curVal>prevVal?'Estimated performance improved by '+f((curVal/prevVal-1)*100)+'%; keep progressing gradually.':'Performance has not exceeded the previous session. Repeat your current load and focus on consistent technique.'}`)});
return `<div class="page-header"><div><h1>Performance <span class="accent">Lab</span></h1><p class="subtitle">Training intelligence calculated from your real results.</p></div>${action('goal-add','＋ Set performance goal','btn primary')}</div><div class="grid cols-4">${metric('THIS WEEK',thisWeek.length+' <span>sessions</span>',`Prior week: ${lastWeek.length}`)}${metric('WORKING SETS',sum(filtered,validSets),'Selected period')}${metric('WEIGHTED VOLUME',f(sum(filtered,volume),0)+' <span>kg</span>','Weighted sets only')}${metric('PR EVENTS',prs.length,'Tracked from your history')}</div><div class="split" style="margin-top:16px"><div class="card"><div class="card-head"><h3>Exercise progression</h3><select class="control flat-select" id="analytics-exercise">${allExercises().map(x=>`<option value="${e(x.id)}" ${x.id===exId?'selected':''}>${e(x.name)}</option>`).join('')}</select></div><div class="row wrap" style="margin-bottom:13px"><span class="tag">${exercise(exId).track==='weight'?'Estimated 1RM (kg)':exercise(exId).track==='time'?'Hold time (seconds)':'Best repetitions'}</span><div class="row">${['30','90','all'].map(v=>`<button data-action="analytics-range" data-range="${v}" class="pill ${range===v?'active':''}">${v==='all'?'All time':v+'d'}</button>`).join('')}</div></div>${trend.length?sparkSVG(trend.map(x=>x.value),'#d2f76c'):empty('▥','No strength history','Log this exercise in a completed session to see its trend.')}<div class="row between"><span class="micro">${trend.length?dateFmt(trend[0].date):'—'}</span><span class="micro">${trend.length?dateFmt(trend.at(-1).date):'—'}</span></div></div><div class="card"><div class="card-head"><h3>Training consistency</h3><span class="tag">Last 8 weeks</span></div>${bars(weekCounts,weekLabels)}<div class="divider"></div><div class="metric-label">Weighted volume by week</div>${bars(weekVolume,weekLabels,'var(--lime)')}<div class="micro">Volume excludes bodyweight, assistance and timed exercises.</div></div></div>
<div class="split" style="margin-top:16px"><div class="card"><div class="card-head"><h3>Muscle group balance</h3><span class="micro">Completed primary-muscle sets, all time</span></div>${Object.keys(counts).length?Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="row" style="gap:12px;margin:13px 0"><span style="width:99px;font-size:12px">${e(k)}</span><div class="bar-meter" style="flex:1"><span style="width:${v/Math.max(...Object.values(counts))*100}%"></span></div><b style="min-width:24px;text-align:right">${v}</b></div>`).join(''):empty('▥','No muscle data yet','Finish workouts to analyze your training distribution.')}</div>
<div class="card"><div class="card-head"><h3>Progression guidance</h3><span class="tag lime">Rule-based</span></div>${recommendations.length?recommendations.slice(0,5).map(x=>`<div class="panel-strip" style="margin:8px 0;align-items:flex-start"><span class="lime-text">↗</span><span style="flex:1;font-size:12px;line-height:1.5">${e(x)}</span></div>`).join(''):empty('◈','Keep logging','After two workouts containing the same weighted exercise, tailored suggestions appear.')}</div></div>
<div class="split" style="margin-top:16px"><div class="card"><div class="card-head"><h3>Performance goals</h3>${action('goal-add','＋ New','btn small')}</div>${state.goals.length?state.goals.map(g=>{let current=goalCurrent(g),pct=Math.min(100,current/Math.max(1,g.target)*100);return `<div class="goal-row"><div class="row between"><b>${e(g.name)}</b>${action('goal-delete','×','tiny-btn',`data-id="${e(g.id)}"`)}</div><div class="row between" style="margin:9px 0"><span class="micro">${f(current)} / ${f(g.target)} ${e(g.metric==='workouts'?'sessions':g.metric==='cardio'?'km':g.metric==='reps'?'reps':'kg')}</span><span class="tag ${pct>=100?'lime':''}">${Math.round(pct)}%</span></div><div class="progress-track"><div class="progress-fill lime" style="width:${pct}%"></div></div></div>`}).join(''):empty('◎','No goals set','Set a measurable bench press, pull-up, session or cardio goal.')}</div>
<div class="card"><div class="card-head"><h3>Recent personal records</h3><span class="tag">${prs.length} milestones</span></div>${prs.length?prs.slice(0,12).map(p=>`<div class="list-item"><div><div class="main-line">${e(exercise(p.exerciseId).name)}</div><div class="sub-line">${e(prLabel(p.metric,p.value))}</div></div><span class="micro">${dateFmt(p.date)}</span></div>`).join(''):empty('★','No personal records yet','PRs are detected by comparing logged sets against earlier workouts.')}</div></div>
<div class="card" style="margin-top:16px"><div class="card-head"><h3>Weekly / monthly report</h3><span class="tag">Current periods</span></div>${periodReport()}</div>`}
function periodReport(){function report(days){let cut=Date.now()-days*864e5,work=state.workouts.filter(x=>new Date(x.finishedAt).getTime()>=cut),cardio=state.cardioSessions.filter(x=>new Date(x.finishedAt||x.createdAt).getTime()>=cut),sleep=state.sleepRecords.filter(x=>new Date(x.date).getTime()>=cut);return `<div class="card soft"><h3>Last ${days} days</h3><div class="divider"></div><div class="list-item"><span>Training sessions</span><b>${work.length}</b></div><div class="list-item"><span>Working sets</span><b>${sum(work,validSets)}</b></div><div class="list-item"><span>Weighted volume</span><b>${f(sum(work,volume),0)} kg</b></div><div class="list-item"><span>Cardio distance</span><b>${f(sum(cardio,x=>x.distanceKm),1)} km</b></div><div class="list-item"><span>Average sleep</span><b>${sleep.length?f(avg(sleep.map(x=>num(x.durationHours))))+' h':'—'}</b></div></div>`}return `<div class="grid cols-2">${report(7)}${report(30)}</div>`}
function nutritionPage(){let dt=view.nutritionDate||day(),d=foodDaily(dt),targets=state.settings.targets;let selectedMeal=view.nutritionMeal||'Breakfast';let meals=['Breakfast','Lunch','Dinner','Snack'];let week=Array.from({length:7},(_,i)=>addDays(dt,i-6));return `<div class="page-header"><div><h1>Fuel Your <span class="accent">Work.</span></h1><p class="subtitle">Nutrition without guesswork. Simple, consistent logging.</p></div>${action('nutrition-add','＋ Log food','btn primary')}</div><div class="row wrap" style="margin-bottom:13px"><div class="field"><label>Log date</label><input type="date" id="nutrition-date" value="${e(dt)}"></div>${action('nutrition-targets','Edit daily targets','btn small')}${action('nutrition-food-create','＋ Custom food','btn small')}${action('nutrition-foods','Food library','btn small')}${action('nutrition-meals','Saved meals','btn small')}</div><div class="grid cols-3">${metric('CALORIES',f(d.kcal,0)+' <span>kcal</span>',`${f(Math.max(0,targets.calories-d.kcal),0)} to target (${targets.calories})`)}${metric('PROTEIN',f(d.protein)+' <span>g</span>',`${f(Math.max(0,targets.protein-d.protein))} g to target (${targets.protein})`)}${metric('FOODS LOGGED',d.entries.length,'Total entries today')}</div>
<div class="split" style="margin-top:16px"><div class="card"><div class="card-head"><h3>Daily nutrition goals</h3><span class="tag">${dateFmt(dt)}</span></div><div class="row between"><b>Calories</b><span>${f(d.kcal,0)} / ${targets.calories} kcal</span></div><div class="progress-track" style="margin:10px 0 21px"><div class="progress-fill" style="width:${Math.min(100,d.kcal/Math.max(1,targets.calories)*100)}%"></div></div><div class="row between"><b>Protein</b><span>${f(d.protein)} / ${targets.protein} g</span></div><div class="progress-track" style="margin:10px 0 21px"><div class="progress-fill lime" style="width:${Math.min(100,d.protein/Math.max(1,targets.protein)*100)}%"></div></div><div class="row between"><span class="muted">Carbohydrates</span><b>${f(d.carbs)} g</b></div><div class="row between" style="margin-top:9px"><span class="muted">Fat</span><b>${f(d.fat)} g</b></div></div>
<div class="card"><div class="card-head"><h3>7-day calorie trend</h3><span class="micro">Logged totals only</span></div>${bars(week.map(x=>foodDaily(x).kcal),week.map(x=>dateFmt(x,{weekday:'short'})))}<div class="info-box">Food reference values are approximate. Your custom entries can match the nutrition labels of the products you use.</div></div></div>
<div class="card" style="margin-top:16px"><div class="card-head"><h3>Meal log</h3>${action('nutrition-add','＋ Add food','btn small primary')}</div>${meals.map(m=>{let entries=d.entries.filter(x=>x.meal===m);return `<div class="session-block"><div class="session-top"><b>${m} <span class="muted">· ${f(sum(entries,x=>foodMacros(x).kcal),0)} kcal</span></b><div class="row">${entries.length?action('meal-save','☆ Save as meal','btn small',`data-meal="${m}" data-date="${dt}"`):''}${action('nutrition-add','＋','btn small',`data-meal="${m}"`)}</div></div>${entries.length?entries.map(x=>{let a=foodMacros(x);return `<div class="list-item"><div><div class="main-line">${e(x.snapshot?.name||food(x.foodId).name)}</div><div class="sub-line">${f(x.amount)} ${e(x.unit==='serving'?'serving(s)':x.unit)} · ${f(a.kcal)} kcal · ${f(a.protein)}g protein</div></div><div class="row">${action('nutrition-edit','Edit','btn small',`data-id="${e(x.id)}"`)}${action('nutrition-delete','×','btn small danger',`data-id="${e(x.id)}"`)}</div></div>`}).join(''):'<div class="micro">No food logged for this meal.</div>'}</div>`}).join('')}</div>`}
function cardioPage(){const c=state.activeCardio,record=[...state.cardioSessions].sort((a,b)=>new Date(b.finishedAt)-new Date(a.finishedAt)),recent=record.slice(0,7);const total=sum(record,x=>x.distanceKm);return `<div class="page-header"><div><h1>Go The <span class="accent">Distance.</span></h1><p class="subtitle">Run, ride, walk. Log every kilometer.</p></div>${action('cardio-add','＋ Manual session','btn primary')}</div><div class="grid cols-3">${metric('TOTAL DISTANCE',f(total)+' <span>km</span>','All-time distance')}${metric('CARDIO SESSIONS',record.length,'Sessions recorded')}${metric('TOTAL TIME',durationFmt(sum(record,x=>x.durationSec)),'All-time active time')}</div><div class="split" style="margin-top:16px"><div class="card emphasis"><div class="card-head"><h3>${c?'Live cardio session':'Start live tracking'}</h3><span class="tag ${c?'lime':'orange'}">${c?(c.pausedAt?'PAUSED':'● LIVE'):'GPS OPTIONAL'}</span></div>${c?`<div class="row between"><div><div class="metric-label">Duration</div><div class="metric" id="cardio-clock">${durationFmt((Date.now()-new Date(c.startedAt).getTime()-num(c.pauseMs))/1000)}</div></div><div><div class="metric-label">Distance</div><div class="metric" id="cardio-distance">${f(c.distanceKm,2)} km</div></div></div><div class="micro">${e(c.type)} · ${c.gpsEnabled?'GPS enabled':'Manual distance entry at finish'}</div>${routeSVG(c.route)}<div class="row wrap" style="margin-top:14px">${action(c.pausedAt?'cardio-resume':'cardio-pause',c.pausedAt?'▶ Resume':'Ⅱ Pause','btn')}${action('cardio-stop','■ Finish and save','btn primary')}${action('cardio-discard','Discard','btn small danger')}</div>`:`<p class="muted">Track activity time live. Enable GPS to estimate routes and distance while this page is open.</p><div class="form-grid" style="margin-bottom:13px"><div class="field"><label>Activity</label><select id="live-cardio-type">${['Running','Walking','Cycling','Hiking','Other'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Location</label><label class="check-row"><input type="checkbox" id="live-cardio-gps"> Use GPS when available</label></div></div>${action('cardio-start','▶ START TRACKING','btn primary full')}<div class="micro" style="margin-top:11px">GPS requires a secure HTTPS or localhost origin and location permission. Background tracking is not guaranteed.</div>`}</div><div class="card"><div class="card-head"><h3>Recent activity</h3><span class="tag">${record.length} saved</span></div>${recent.length?recent.map(x=>`<div class="list-item"><div><div class="main-line">${e(x.type)}</div><div class="sub-line">${dateFmt(x.finishedAt||x.date)} · ${durationFmt(x.durationSec)}</div></div><div class="row"><b>${f(x.distanceKm,2)} km</b>${action('cardio-view','View','btn small',`data-id="${e(x.id)}"`)}</div></div>`).join(''):empty('↗','No cardio sessions','Start a live timer or manually add your previous runs and rides.')}</div></div>
<div class="card" style="margin-top:16px"><div class="card-head"><h3>Distance progression</h3><span class="tag">Last 8 sessions</span></div>${record.length?sparkSVG(record.slice(0,8).reverse().map(x=>x.distanceKm),'#d2f76c'):empty('↗','Nothing to chart','Finish cardio sessions to build your distance chart.')}</div>`}
function routeSVG(route){if(!route?.length)return `<div class="gps-map" style="display:grid;place-items:center;margin-top:14px"><span class="micro">No route coordinates recorded</span></div>`;let lats=route.map(x=>x.lat),lons=route.map(x=>x.lon),minLat=Math.min(...lats),maxLat=Math.max(...lats),minLon=Math.min(...lons),maxLon=Math.max(...lons);let pts=route.map(x=>[10+(x.lon-minLon)/(maxLon-minLon||1)*580,170-(10+(x.lat-minLat)/(maxLat-minLat||1)*150)]).map(x=>x.join(',')).join(' ');return `<div class="gps-map" style="margin-top:12px"><svg viewBox="0 0 600 180" preserveAspectRatio="xMidYMid meet"><polyline points="${pts}" stroke="#d2f76c" stroke-width="4" stroke-linecap="round" stroke-linejoin="round" fill="none"/><circle cx="${pts.split(' ').at(-1).split(',')[0]}" cy="${pts.split(' ').at(-1).split(',')[1]}" r="7" fill="#ff663d"/></svg></div><div class="micro" style="margin-top:5px">Route shape only — no map tiles or internet service.</div>`}
function sleepPage(){const all=[...state.sleepRecords].sort((a,b)=>b.date.localeCompare(a.date)),last=all[0],week=all.filter(x=>new Date(x.date).getTime()>Date.now()-7*864e5);return `<div class="page-header"><div><h1>Rest. <span class="accent">Rebuild.</span></h1><p class="subtitle">Sleep is part of the training.</p></div><div class="page-actions">${action('sleep-quick','＋ Quick log','btn primary')}${action('sleep-detailed','Detailed log','btn')}</div></div><div class="grid cols-3">${metric('LAST NIGHT',last?f(last.durationHours)+' <span>hours</span>':'—','Latest sleep record')}${metric('7-DAY AVERAGE',week.length?f(avg(week.map(x=>x.durationHours)))+' <span>hours</span>':'—',`${week.length} records in last 7 days`)}${metric('SLEEP QUALITY',last?f(last.quality,0)+' <span>/ 5</span>':'—','Latest self-rating')}</div><div class="split" style="margin-top:16px"><div class="card"><div class="card-head"><h3>Sleep duration</h3><span class="tag">Recent entries</span></div>${all.length?sparkSVG(all.slice(0,12).reverse().map(x=>x.durationHours),'#d2f76c'):empty('☾','No sleep data yet','Log your sleep to identify your patterns.')}</div><div class="card"><div class="card-head"><h3>Sleep quality</h3><span class="tag">1–5 scale</span></div>${all.length?bars(all.slice(0,7).reverse().map(x=>x.quality),all.slice(0,7).reverse().map(x=>dateFmt(x.date,{weekday:'short'}))):empty('☾','No quality ratings','Sleep quality ratings will appear here.')}</div></div><div class="card" style="margin-top:16px"><div class="card-head"><h3>Sleep history</h3><span class="tag">${all.length} entries</span></div>${all.length?all.map(x=>`<div class="list-item"><div><div class="main-line">${dateFmt(x.date,{weekday:'short',month:'short',day:'numeric'})} — ${f(x.durationHours)} hours</div><div class="sub-line">Quality ${e(x.quality)}/5 ${x.bedtime?'· '+e(x.bedtime)+' to '+e(x.wakeup):''}${x.awakenings?' · '+e(x.awakenings)+' awakenings':''}${x.naps?' · '+e(x.naps)+' min nap':''}${x.notes?' · '+e(limit(x.notes,55)):''}</div></div><div class="row">${action('sleep-edit','Edit','btn small',`data-id="${e(x.id)}"`)}${action('sleep-delete','×','btn small danger',`data-id="${e(x.id)}"`)}</div></div>`).join(''):empty('☾','No sleep entries','Use quick logging or fill in detailed sleep information.')}</div>`}
function settingsPage(){const s=state.settings;return `<div class="page-header"><div><h1>App <span class="accent">Settings</span></h1><p class="subtitle">Your data stays yours. No account required.</p></div></div><div class="split"><div class="card"><div class="card-head"><h3>Training preferences</h3><span class="tag">Personal defaults</span></div><form data-form="settings"><div class="form-grid">${field('days','Default workout days/week',s.days,'number','min="1" max="7"')}${selectField('experience','Experience',['beginner','intermediate','advanced'].map(x=>[x,cap(x)]),s.experience)}${selectField('scheduleMode','Program schedule',[['flex','Flexible sequence'],['fixed','Fixed weekdays']],s.scheduleMode)}${selectField('environment','Default environment',[['gym','Gym'],['home','Home']],s.environment)}${field('restSeconds','Rest timer (seconds)',s.restSeconds,'number','min="0" max="600"')}</div><div class="modal-actions"><button type="submit" class="btn primary">Save preferences</button></div></form></div><div class="card"><div class="card-head"><h3>Data safety</h3><span class="tag ${persistent?'lime':'red'}">${persistent?'LOCAL STORAGE READY':'STORAGE UNAVAILABLE'}</span></div><div class="info-box">Your records are saved in this browser's IndexedDB. Clearing browser/site data or removing an app may delete them. Export backups regularly and keep them somewhere safe.</div><div class="stack" style="margin-top:15px">${action('backup-export','↓ Export complete JSON backup','btn full primary')}${action('backup-import','↑ Restore from JSON backup','btn full')}${action('csv-all','↓ Export data to CSV…','btn full')}${action('backup-help','Backup and install instructions','btn full ghost')}</div></div></div>
<div class="split" style="margin-top:16px"><div class="card"><div class="card-head"><h3>Gym equipment</h3><span class="tag">Customize</span></div><div class="grid cols-2">${EQUIPMENT.map(x=>`<label class="check-row"><input type="checkbox" data-equipment="gym" value="${e(x)}" ${s.gymEquipment.includes(x)?'checked':''}><span>${e(x)}</span></label>`).join('')}</div></div><div class="card"><div class="card-head"><h3>Home equipment</h3><span class="tag">Customize</span></div><div class="grid cols-2">${EQUIPMENT.map(x=>`<label class="check-row"><input type="checkbox" data-equipment="home" value="${e(x)}" ${s.homeEquipment.includes(x)?'checked':''}><span>${e(x)}</span></label>`).join('')}</div></div></div>
<div class="card" style="margin-top:16px"><div class="card-head"><h3>App information</h3></div><div class="row between"><span>Version</span><span class="tag">1.1</span></div><div class="divider"></div><div class="row between"><span>Cloud synchronization</span><span class="tag">None • Private</span></div><div class="divider"></div><div class="row between"><span>Personal data</span><span class="tag">Stored locally only</span></div><div class="divider"></div><div class="row between"><span>Backend / paid APIs</span><span class="tag">None</span></div><div class="divider"></div><div class="micro">FORGE uses metric units and includes built-in reference food/exercise data. The interface and workout generator use no external services.</div></div>`}
const pages={home:homePage,workout:workoutPage,programs:programsPage,exercises:exercisesPage,progress:progressPage,analytics:analyticsPage,nutrition:nutritionPage,cardio:cardioPage,sleep:sleepPage,settings:settingsPage};
/* Forms and editor dialogs */
function dialog(title,intro,fields,formName,submit='Save',wide=false){showModal(`<h2>${e(title)}</h2><p class="modal-intro">${e(intro)}</p><form data-form="${formName}">${fields}${formButtons(submit)}</form>`,wide)}
function generateDialog(){dialog('Generate training program','Build a free, rules-based program. No AI account or internet needed.',`<div class="form-grid">${field('days','Sessions per week',state.settings.days,'number','min="1" max="7"')}${selectField('duration','Target minutes',[30,45,60,75,90,120].map(x=>[x,x+' minutes']),60)}${selectField('environment','Available equipment',[['gym','Gym equipment'],['home','Home equipment']],state.settings.environment)}${selectField('experience','Your experience',[['beginner','Beginner'],['intermediate','Intermediate'],['advanced','Advanced']],state.settings.experience)}</div><div class="info-box" style="margin-top:15px">Includes strength, accessible calisthenics, and mobility. Review and adjust exercise selection, reps and loads for your experience.</div>`,'program-generate','Generate and save')}
function programDialog(id){const p=state.programs.find(x=>x.id===id);dialog(p?'Edit program':'Create manual program',p?'Update details without losing sessions.':'Start with an empty program and add training sessions.',`<input type="hidden" name="id" value="${e(id||'')}">${field('name','Program name',p?.name||'My Training Plan','','required maxlength="90"')}${textareaField('description','Description',p?.description||'')}${selectField('environment','Primary environment',[['gym','Gym'],['home','Home']],p?.environment||state.settings.environment)}`,'program-save',p?'Save changes':'Create program')}
function sessionDialog(programId,sessionId){const p=state.programs.find(x=>x.id===programId),ss=p?.sessions.find(x=>x.id===sessionId);if(!p)return;const s=ss||{id:'',name:`Session ${p.sessions.length+1}`,weekday:p.sessions.length%7,exercises:[]};const xs=s.exercises.map((x,i)=>`<div class="session-block" data-edit-row="${e(x.uid)}"><div class="row between"><b>${e(exercise(x.exerciseId).name)}</b>${action('session-ex-remove','×','tiny-btn',`data-program="${e(p.id)}" data-session="${e(s.id)}" data-ex="${e(x.uid)}"`)}</div><div class="form-grid" style="grid-template-columns:repeat(3,1fr);margin-top:11px">${field('count-'+e(x.uid),'Sets',x.sets,'number','min="1" max="12"')}${field('reps-'+e(x.uid),exercise(x.exerciseId).track==='time'?'Seconds':'Target reps',x.reps,'number','min="1" max="300"')}${field('rest-'+e(x.uid),'Rest seconds',x.rest,'number','min="0" max="600"')}</div><div class="micro" style="margin-top:6px">${e(exercise(x.exerciseId).primary)} · ${e(exercise(x.exerciseId).equipment)}</div></div>`).join('');dialog(ss?'Edit workout session':'Add training session','Adjust session details and set targets. Use Add Exercise to expand your routine.',`<input name="programId" type="hidden" value="${e(p.id)}"><input name="sessionId" type="hidden" value="${e(s.id)}">${field('name','Session name',s.name,'text','required maxlength="90"')}${selectField('weekday','Scheduled day',[['0','Monday'],['1','Tuesday'],['2','Wednesday'],['3','Thursday'],['4','Friday'],['5','Saturday'],['6','Sunday']],s.weekday)}<div class="section-header"><h3>Exercises (${s.exercises.length})</h3>${action('session-ex-pick','＋ Add Exercise','btn small',`data-program="${e(p.id)}" data-session="${e(s.id)}"`)}</div>${xs||empty('◇','No exercises','Add an exercise from the built-in library.')}`,'session-save','Save session',true)}
function pickExercise(context,programId='',sessionId=''){const items=allExercises().filter(x=>context!=='session'||true);showModal(`<h2>Choose an exercise</h2><p class="modal-intro">Tap an exercise to add it. All available exercises are listed.</p><div class="field" style="margin-bottom:10px"><label>Search the library</label><input id="picker-search" placeholder="Start typing to search…" autofocus></div><div id="picker-list" class="item-scroll">${pickerItems(items,context,programId,sessionId)}</div><div class="modal-actions">${action('close-modal','Done','btn')}</div>`,true)}
function pickerItems(items,context,programId,sessionId){return items.map(x=>`<div class="list-item picker-result" data-label="${e((x.name+' '+x.primary).toLowerCase())}"><div><b>${e(x.name)}</b><div class="micro">${e(x.primary)} · ${e(x.equipment)} · ${e(x.kind)}</div></div>${action('picker-add','＋ Add','btn small primary',`data-context="${context}" data-exercise="${e(x.id)}" data-program="${e(programId)}" data-session="${e(sessionId)}"`)}</div>`).join('')}
function exerciseDialog(id){const x=state.exercises.find(x=>x.id===id);dialog(x?'Edit custom exercise':'Create custom exercise','A custom entry will appear alongside the built-in exercise library.',`<input name="id" type="hidden" value="${e(id||'')}"><div class="form-grid">${field('name','Exercise name',x?.name||'','text','required maxlength="90"')}${selectField('primary','Primary muscle',['Chest','Back','Shoulders','Biceps','Triceps','Quads','Hamstrings','Glutes','Calves','Core','Mobility','Other'],x?.primary||'Chest')}${field('secondary','Secondary muscles',x?.secondary||'')}${selectField('equipment','Equipment',EQUIPMENT,x?.equipment||'Bodyweight')}${selectField('kind','Training type',[['strength','Strength'],['calisthenics','Calisthenics'],['mobility','Mobility']],x?.kind||'strength')}${selectField('track','Track as',[['weight','Weight + reps'],['bodyweight','Bodyweight reps'],['assisted','Assisted reps'],['time','Timed holds']],x?.track||'weight')}${selectField('difficulty','Difficulty',['Beginner','Intermediate','Advanced'],x?.difficulty||'Beginner')}</div>${textareaField('instructions','Technique instructions',x?.instructions||'')}${x?`<div style="margin-top:10px">${action('exercise-delete','Delete exercise','btn small danger',`data-id="${e(id)}"`)}</div>`:''}`,'exercise-save',x?'Update exercise':'Create exercise')}
function exerciseDetails(id){const x=exercise(id),hist=exerciseHistory(id),prs=derivePRs().filter(p=>p.exerciseId===id);showModal(`<div class="row between"><span class="tag orange">${e(x.kind)}</span>${action('close-modal','×','btn small')}</div><h2 style="margin-top:15px">${e(x.name)}</h2><p class="modal-intro">${e(x.primary)} · ${e(x.equipment)} · ${e(x.difficulty)}</p><div class="info-box">${e(x.instructions)}. Track type: ${e(x.track)}.</div><div class="section-header"><h3>Exercise history</h3><span class="tag">${hist.length} sessions</span></div>${hist.length?hist.slice(0,12).map(w=>{let ex=w.exercises.find(y=>y.exerciseId===id);return `<div class="list-item"><div><b>${dateFmt(w.finishedAt)}</b><div class="micro">${ex.sets.filter(s=>s.complete&&!s.skipped).map(s=>x.track==='time'?s.durationSec+'s':x.track==='weight'?`${s.weight}kg × ${s.reps}`:`${s.reps} reps`).join(' · ')}</div></div></div>`}).join(''):empty('◈','No performance yet','Your previous sets will appear here.')}<div class="section-header"><h3>Personal records</h3><span class="tag">${prs.length}</span></div>${prs.slice(0,7).map(p=>`<div class="list-item"><span>${e(prLabel(p.metric,p.value))}</span><span class="micro">${dateFmt(p.date)}</span></div>`).join('')||'<div class="micro">No improved records recorded yet.</div>'}`,true)}
function bodyDialog(id){const r=state.bodyRecords.find(x=>x.id===id);dialog(r?'Edit body measurement':'Log body measurement','Leave optional measurements blank. Body fat entries are estimates.',`<input type="hidden" name="id" value="${e(id||'')}"><div class="form-grid">${field('date','Date',r?.date||day(),'date','required')}${field('weight','Body weight (kg)',r?.weight??'','number','min="0" max="500" step="0.1"')}${field('bodyFat','Body fat % (estimate)',r?.bodyFat??'','number','min="0" max="100" step="0.1"')}${['chest','waist','arms','shoulders','hips','thighs'].map(x=>field(x,label(x)+' (cm)',r?.[x]??'','number','min="0" max="400" step="0.1"')).join('')}</div>`,'body-save')}
function goalDialog(){dialog('Set performance goal','Choose a measurable target. Current progress is calculated from your recorded sessions.',`${field('name','Goal name','15 pull-ups','text','required maxlength="90"')}${selectField('metric','Goal metric',[['reps','Maximum reps in one set'],['weight','Heaviest weight (kg)'],['e1rm','Estimated 1RM (kg)'],['workouts','Total completed workouts'],['cardio','Total cardio distance (km)']],'reps')}${selectField('exerciseId','Exercise (ignored for total sessions or cardio)',allExercises().map(x=>[x.id,x.name]),'pullup')}${field('target','Target value','15','number','required min="0.01" step="0.1"')}`,'goal-save','Create goal')}
function nutritionDialog(id='',meal='Breakfast'){const x=state.foodLogs.find(x=>x.id===id),item=food(x?.foodId||FOODS[0].id);dialog(x?'Edit food entry':'Log food to meal','Choose a food and quantity. Nutrients are calculated automatically.',`<input type="hidden" name="id" value="${e(id)}"><div class="form-grid">${field('date','Date',x?.date||view.nutritionDate||day(),'date','required')}${selectField('meal','Meal',['Breakfast','Lunch','Dinner','Snack'],x?.meal||meal)}</div><div class="field" style="margin-top:12px"><label>Searchable food</label><input id="food-select-search" placeholder="Find a food…" value=""></div><div class="field" style="margin:7px 0 12px"><select id="foodId" name="foodId" size="7" style="height:160px">${allFoods().map(y=>`<option value="${e(y.id)}" ${item.id===y.id?'selected':''}>${e(y.name)}${y.custom?' (custom)':''}</option>`).join('')}</select></div><div class="form-grid">${field('amount','Quantity',x?.amount||item.serving,'number','required min="0.1" step="0.1"')}${selectField('unit','Unit',[['g','grams'],['ml','milliliters'],['serving','serving(s)']],x?.unit||item.unit)}</div><div class="info-box" style="margin-top:13px">Use grams for solid foods, milliliters for liquids, or servings. Entries scale nutrition from the selected food's 100-unit reference.</div>`,'nutrition-save','Log food',true)}
function customFoodDialog(id){const x=state.foodsCustom.find(x=>x.id===id);dialog(x?'Edit custom food':'New custom food','Enter values per 100 grams or per 100 milliliters, following the product label.',`<input type="hidden" name="id" value="${e(id||'')}">${field('name','Food name',x?.name||'','text','required maxlength="100"')}<div class="form-grid">${selectField('unit','Base unit',[['g','Per 100 grams'],['ml','Per 100 milliliters']],x?.unit||'g')}${field('serving','Serving size (in base units)',x?.serving||100,'number','required min="0.1" step="0.1"')}${field('kcal','Calories per 100',x?.kcal??0,'number','required min="0" step="0.1"')}${field('protein','Protein (g) per 100',x?.protein??0,'number','required min="0" step="0.1"')}${field('carbs','Carbs (g) per 100',x?.carbs??0,'number','required min="0" step="0.1"')}${field('fat','Fat (g) per 100',x?.fat??0,'number','required min="0" step="0.1"')}</div>`,'food-save')}
function foodLibraryDialog(){showModal(`<div class="row between"><h2>Food library</h2>${action('close-modal','×','btn small')}</div><p class="modal-intro">Food values are indicative reference data; custom foods use your values.</p><div class="field"><input id="food-list-search" placeholder="Search foods…"></div><div id="food-list-results" class="item-scroll">${foodLibraryRows()}</div><div class="modal-actions">${action('nutrition-food-create','＋ New custom food','btn primary')}</div>`,true)}
function foodLibraryRows(){return allFoods().map(x=>`<div class="list-item food-result" data-label="${e(x.name.toLowerCase())}"><div><b>${e(x.name)}</b><div class="micro">Per 100 ${e(x.unit)}: ${f(x.kcal)} kcal · ${f(x.protein)} g protein ${x.custom?'· custom':'· approx.'}</div></div><div class="row">${action('food-favorite',state.foodFavorites.includes(x.id)?'★':'☆','tiny-btn',`data-id="${e(x.id)}"`)}${x.custom?action('nutrition-food-edit','Edit','btn small',`data-id="${e(x.id)}"`):''}</div></div>`).join('')}
function savedMealsDialog(){showModal(`<h2>Saved meals</h2><p class="modal-intro">Save your logged breakfast, lunch, dinner or snacks and reuse them quickly.</p>${state.savedMeals.length?state.savedMeals.map(m=>`<div class="list-item"><div><b>${e(m.name)}</b><div class="micro">${m.items.length} food items · ${f(sum(m.items,x=>foodMacros(x).kcal))} kcal</div></div><div class="row">${action('saved-meal-use','＋ Log','btn small primary',`data-id="${e(m.id)}"`)}${action('saved-meal-delete','×','btn small danger',`data-id="${e(m.id)}"`)}</div></div>`).join(''):empty('◌','No saved meals','Log foods in a meal and use Save as meal.')}<div class="modal-actions">${action('close-modal','Close','btn')}</div>`,true)}
function cardioDialog(id){const x=state.cardioSessions.find(x=>x.id===id);dialog(x?'Edit cardio session':'Manual cardio session','Log a treadmill run, walk, bike ride, or an activity recorded elsewhere.',`<input type="hidden" name="id" value="${e(id||'')}"><div class="form-grid">${field('date','Activity date',x?.date||day(),'date','required')}${selectField('type','Activity',['Running','Walking','Cycling','Hiking','Other'],x?.type||'Running')}${field('minutes','Duration (minutes)',x?round(x.durationSec/60,1):30,'number','required min="0.1" step="0.1"')}${field('distanceKm','Distance (km)',x?.distanceKm??0,'number','required min="0" step="0.01"')}</div>${textareaField('notes','Notes',x?.notes||'')}`,'cardio-save',x?'Save changes':'Save cardio')}
function cardioDetail(id){let x=state.cardioSessions.find(x=>x.id===id);if(!x)return;showModal(`<div class="row between"><h2>${e(x.type)}</h2>${action('close-modal','×','btn small')}</div><p class="modal-intro">${dateFmt(x.finishedAt||x.date,{month:'short',day:'numeric',year:'numeric'})} · ${x.mode==='live'?'Live tracked':'Manually logged'}</p><div class="grid cols-2">${metric('DISTANCE',f(x.distanceKm,2)+' km')}${metric('DURATION',durationFmt(x.durationSec))}</div><div class="divider"></div><div class="row between"><span>Average pace</span><b>${x.distanceKm>0?f(x.durationSec/60/x.distanceKm,1)+' min/km':'—'}</b></div><p class="micro">${e(x.notes||'')}</p>${routeSVG(x.route)}<div class="modal-actions">${action('cardio-delete','Delete','btn danger',`data-id="${e(x.id)}"`)}${action('cardio-edit','Edit','btn',`data-id="${e(x.id)}"`)}${action('close-modal','Close','btn')}</div>`,true)}
function sleepDialog(detailed=false,id){let x=state.sleepRecords.find(y=>y.id===id);if(x?.bedtime)detailed=true;dialog(x?'Edit sleep entry':detailed?'Detailed sleep log':'Quick sleep log','Record what you know. You can edit this entry later.',`<input type="hidden" name="id" value="${e(id||'')}"><input type="hidden" name="mode" value="${detailed?'detailed':'quick'}"><div class="form-grid">${field('date','Sleep date',x?.date||day(),'date','required')}${selectField('quality','Sleep quality',[1,2,3,4,5].map(v=>[v,v+' / 5']),x?.quality||3)}${detailed?`${field('bedtime','Bedtime',x?.bedtime||'23:00','time','required')}${field('wakeup','Wake-up time',x?.wakeup||'07:00','time','required')}${field('awakenings','Night awakenings',x?.awakenings??0,'number','min="0" max="99"')}${field('naps','Naps (minutes)',x?.naps??0,'number','min="0" max="600"')}`:field('durationHours','Hours slept',x?.durationHours??8,'number','required min="0.1" max="24" step="0.1"')}</div>${detailed?textareaField('notes','Notes',x?.notes||''):''}`,'sleep-save')}
function backupHelp(){showModal(`<h2>Storage, installation & backups</h2><p class="modal-intro">Read this before trusting the app with months of records.</p><div class="stack"><div class="info-box"><b>Where your data lives:</b> Your current browser's IndexedDB. There is no server and no account. Site data may be deleted by clearing storage, private browsing, system cleanup, or uninstalling the web app.</div><div class="info-box"><b>Backups:</b> Open Settings → Export complete JSON backup. Save the file in Files, iCloud Drive, a USB drive or wherever you choose. Restore using Import JSON, which replaces the current app data only after validation and confirmation. CSV exports are for analysis and cannot be re-imported.</div><div class="info-box"><b>Installing:</b> Serve these files from a secure HTTPS site or from localhost. Open the site in Safari on iPhone → Share → Add to Home Screen. On desktop, use your browser's Install option. Opening an HTML file directly may not support PWA install or reliable IndexedDB, depending on the browser.</div><div class="info-box"><b>Offline:</b> Once loaded through a supported origin, the service worker caches the app shell. GPS normally requires permission, HTTPS and an active tab; tracking can stop in the background.</div></div><div class="modal-actions">${action('close-modal','Got it','btn primary')}</div>`,true)}
/* Event handlers and persistence */
function byId(id,arr){return arr.find(x=>x.id===id)}
function editActiveSet(btn){const w=state.activeWorkout,x=w?.exercises.find(x=>x.uid===btn.dataset.ex),s=x?.sets.find(s=>s.id===btn.dataset.set);return {w,x,s}}
function chooseSession(programId,sessionId){const p=byId(programId,state.programs),ss=p?.sessions.find(x=>x.id===sessionId);if(!ss)return toast('Session not found.','error');if(state.activeWorkout)return toast('Finish or discard your current workout first.','error');update(st=>{st.activeWorkout={id:uid(),programId,sessionId,name:ss.name,startedAt:now(),restUntil:null,exercises:ss.exercises.map(pr=>sessionToActive(pr))}});navigate('workout');toast('Workout started. All changes are autosaved.')}
function quickStart(){if(state.activeWorkout)return navigate('workout');update(st=>{st.activeWorkout={id:uid(),programId:null,sessionId:null,name:'Freestyle Workout',startedAt:now(),restUntil:null,exercises:[]}});navigate('workout')}
function setDone(btn,skip=false){const {w,x,s}=editActiveSet(btn);if(!s)return;if(skip){s.skipped=!s.skipped;s.complete=false}else{if(!s.complete){const ex=exercise(x.exerciseId);if(ex.track==='time'){if(num(s.durationSec)<=0)return toast('Enter a hold duration above zero.','error')}else if(num(s.reps)<1)return toast('Enter at least one repetition.','error');if(ex.track==='weight'&&num(s.weight)<0)return toast('Weight cannot be negative.','error')}s.complete=!s.complete;s.skipped=false;if(s.complete&&num(x.restSec)>0)w.restUntil=Date.now()+num(x.restSec)*1000}save();render()}
function finishWorkout(){const w=state.activeWorkout;if(!w)return;if(!validSets(w)){if(!confirm('No completed working sets were logged. Save this workout anyway?'))return}const completed={...structuredClone(w),finishedAt:w.originalFinishedAt||now(),durationSec:w.originalDurationSec??Math.max(0,Math.round((Date.now()-new Date(w.startedAt).getTime())/1000))};delete completed.restUntil;delete completed.editOriginalId;delete completed.originalFinishedAt;delete completed.originalDurationSec;if(!confirm(`Finish "${w.name}" and save ${validSets(w)} completed sets?`))return;update(s=>{if(w.editOriginalId){let idx=s.workouts.findIndex(x=>x.id===w.editOriginalId);if(idx>=0)s.workouts[idx]=completed;else s.workouts.push(completed)}else s.workouts.push(completed);if(!w.editOriginalId&&s.settings.scheduleMode==='flex'&&s.settings.selectedProgramId===w.programId){const p=activeProgram();if(p&&p.sessions[s.settings.pointer%p.sessions.length]?.id===w.sessionId)s.settings.pointer=(s.settings.pointer+1)%p.sessions.length}s.activeWorkout=null});navigate('workout');toast('Workout saved to history. Strong work.')}
function btnClick(ev){const b=ev.target.closest('[data-action]');if(!b)return;let a=b.dataset.action,id=b.dataset.id,programId=b.dataset.program,sessionId=b.dataset.session;const p=byId(programId,state.programs);switch(a){
case 'nav':navigate(b.dataset.page);break;case 'go-home':navigate('home');break;case 'open-settings':navigate('settings');break;case 'mobile-more':showModal(`<h2>Explore FORGE</h2><p class="modal-intro">All your training tools in one place.</p><div class="grid cols-2">${NAV.map(n=>action('nav',n[1]+' '+n[2],'btn',`data-page="${n[0]}"`)).join('')}</div><div class="modal-actions">${action('close-modal','Close','btn')}</div>`);break;case 'overlay':if(ev.target===b)closeModal();break;case 'close-modal':closeModal();break;
case 'generate-program':generateDialog();break;case 'create-program':programDialog();break;case 'program-view':view.programId=id;render();break;case 'program-back':delete view.programId;render();break;case 'program-edit':programDialog(id);break;case 'program-session-add':sessionDialog(id,'');break;case 'program-activate':update(s=>{s.settings.selectedProgramId=id;s.settings.pointer=0});toast('Active program updated.');break;
case 'program-duplicate':{let src=byId(id,state.programs);if(!src)break;let copy=structuredClone(src);copy.id=uid();copy.name=src.name+' (Copy)';copy.createdAt=now();copy.sessions.forEach(ss=>{ss.id=uid();ss.exercises.forEach(x=>x.uid=uid())});update(s=>s.programs.push(copy));view.programId=copy.id;render();toast('Program duplicated.');break}
case 'program-delete':if(!confirm('Delete this program? Completed workout history remains saved.'))break;update(s=>{s.programs=s.programs.filter(p=>p.id!==id);if(s.settings.selectedProgramId===id){s.settings.selectedProgramId=null;s.settings.pointer=0}});delete view.programId;render();break;
case 'session-edit':sessionDialog(programId,sessionId);break;case 'session-delete':if(!confirm('Delete this workout session from your program?'))break;update(s=>{const p=byId(programId,s.programs);p.sessions=p.sessions.filter(x=>x.id!==sessionId)});break;
case 'session-ex-pick':{const form=b.closest('form');if(form){const result=saveSession(form,true);if(!result)return;pickExercise('session',result.programId,result.sessionId)}else pickExercise('session',programId,sessionId);break}
case 'session-ex-remove':{if(!confirm('Remove this exercise from the session?'))break;const form=b.closest('form');if(form){const result=saveSession(form,true);if(!result)return;programId=result.programId;sessionId=result.sessionId}update(s=>{const ss=byId(programId,s.programs)?.sessions.find(x=>x.id===sessionId);if(ss)ss.exercises=ss.exercises.filter(x=>x.uid!==b.dataset.ex)});sessionDialog(programId,sessionId);break}
case 'picker-add':{const exId=b.dataset.exercise;if(b.dataset.context==='session'){const ss=byId(programId,state.programs)?.sessions.find(x=>x.id===sessionId);if(!ss)return toast('Session not found.','error');update(s=>{byId(programId,s.programs).sessions.find(x=>x.id===sessionId).exercises.push(newSessionExercise(exId,exercise(exId).kind==='mobility'?2:3,exercise(exId).track==='time'?30:10,90))});sessionDialog(programId,sessionId)}else{update(s=>s.activeWorkout.exercises.push(sessionToActive(newSessionExercise(exId,3,exercise(exId).track==='time'?30:10,90))));closeModal();toast('Exercise added to workout.')}break}
case 'start-session':chooseSession(programId,sessionId);break;case 'start-next':{let n=nextSession();if(n)chooseSession(n.program.id,n.session.id);break}case 'quick-start':quickStart();break;
case 'exercise-create':exerciseDialog();break;case 'exercise-edit':exerciseDialog(id);break;case 'exercise-details':exerciseDetails(id);break;
case 'exercise-favorite':update(s=>s.favorites=s.favorites.includes(id)?s.favorites.filter(x=>x!==id):[...s.favorites,id]);break;case 'favorites-toggle':view.favoritesOnly=!view.favoritesOnly;render();break;
case 'exercise-delete':if(!confirm('Delete this custom exercise? Historical records referencing it will show a deleted exercise placeholder.'))break;update(s=>s.exercises=s.exercises.filter(x=>x.id!==id));closeModal();break;
case 'workout-rename':{let name=prompt('Workout name',state.activeWorkout?.name||'');if(name?.trim())update(s=>s.activeWorkout.name=name.trim().slice(0,90));break}
case 'workout-add-exercise':pickExercise('workout');break;
case 'workout-ex-remove':if(!confirm('Remove this exercise and its sets from the current workout?'))break;update(s=>s.activeWorkout.exercises=s.activeWorkout.exercises.filter(x=>x.uid!==b.dataset.ex));break;
case 'workout-ex-move':{let i=state.activeWorkout.exercises.findIndex(x=>x.uid===b.dataset.ex),j=i+num(b.dataset.direction);if(i<0||j<0||j>=state.activeWorkout.exercises.length)break;update(s=>{let ex=s.activeWorkout.exercises;[ex[i],ex[j]]=[ex[j],ex[i]]});break}
case 'set-add':update(s=>{let x=s.activeWorkout.exercises.find(x=>x.uid===b.dataset.ex);let last=x.sets.at(-1)||{reps:10,weight:0,assisted:0,durationSec:30,rpe:'',rir:''};x.sets.push({...last,id:uid(),complete:false,skipped:false})});break;
case 'set-remove':{let {x,s}=editActiveSet(b);if(!x||!s)break;update(()=>x.sets=x.sets.filter(z=>z.id!==s.id));break}
case 'set-done':setDone(b,false);break;case 'set-skip':setDone(b,true);break;
case 'rest-add':update(s=>s.activeWorkout.restUntil=(s.activeWorkout.restUntil||Date.now())+15000);break;case 'rest-skip':update(s=>s.activeWorkout.restUntil=null);break;
case 'workout-finish':finishWorkout();break;case 'workout-abandon':if(!confirm('Discard the active workout and all its unsaved session data?'))break;update(s=>s.activeWorkout=null);navigate('workout');break;
case 'workout-detail':{let w=byId(id,state.workouts);if(!w)break;showModal(`<div class="row between"><h2>${e(w.name)}</h2>${action('close-modal','×','btn small')}</div><p class="modal-intro">${dateFmt(w.finishedAt,{year:'numeric',month:'short',day:'numeric'})} · ${durationFmt(w.durationSec)} · ${validSets(w)} working sets</p><div class="grid cols-2">${metric('VOLUME',f(volume(w),0)+' kg')}${metric('EXERCISES',w.exercises.length)}</div><div class="divider"></div>${w.exercises.map(x=>`<div class="session-block"><b>${e(exercise(x.exerciseId).name)}</b><div class="micro">${x.sets.filter(s=>s.complete&&!s.skipped).map(s=>exercise(x.exerciseId).track==='time'?`${s.durationSec}s`:`${s.weight||0} kg × ${s.reps||0}`).join(' / ')||'No completed sets'}</div>${x.notes?`<p class="micro">${e(x.notes)}</p>`:''}</div>`).join('')}<div class="modal-actions">${action('workout-delete','Delete workout','btn danger',`data-id="${e(w.id)}"`)}${action('workout-history-edit','Edit session','btn',`data-id="${e(w.id)}"`)}${action('close-modal','Close','btn')}</div>`,true);break}
case 'workout-history-edit':{if(state.activeWorkout)return toast('Finish your active session first.','error');let w=byId(id,state.workouts);if(!w)break;update(s=>{s.activeWorkout={...structuredClone(w),startedAt:now(),editOriginalId:id,originalFinishedAt:w.finishedAt,originalDurationSec:w.durationSec,restUntil:null}});closeModal();navigate('workout');toast('Editing historical session. Finish to apply changes or discard to retain the original.');break}
case 'workout-delete':if(!confirm('Delete this saved workout permanently? PRs and analytics will be recalculated.'))break;update(s=>s.workouts=s.workouts.filter(x=>x.id!==id));closeModal();break;
case 'body-add':bodyDialog();break;case 'body-edit':bodyDialog(id);break;case 'body-delete':if(!confirm('Delete this body measurement?'))break;update(s=>s.bodyRecords=s.bodyRecords.filter(x=>x.id!==id));break;
case 'goal-add':goalDialog();break;case 'goal-delete':if(!confirm('Delete this goal?'))break;update(s=>s.goals=s.goals.filter(x=>x.id!==id));break;
case 'analytics-range':view.range=b.dataset.range;render();break;
case 'nutrition-add':nutritionDialog('',b.dataset.meal||'Breakfast');break;case 'nutrition-edit':nutritionDialog(id);break;case 'nutrition-delete':if(!confirm('Delete this food entry?'))break;update(s=>s.foodLogs=s.foodLogs.filter(x=>x.id!==id));break;
case 'nutrition-targets':dialog('Daily nutrition targets','Customize your calorie and protein goals.',`${field('calories','Calories per day',state.settings.targets.calories,'number','required min="1" max="20000"')}${field('protein','Protein per day (g)',state.settings.targets.protein,'number','required min="1" max="1000"')}`,'nutrition-target-save');break;
case 'nutrition-food-create':customFoodDialog();break;case 'nutrition-food-edit':customFoodDialog(id);break;case 'nutrition-foods':foodLibraryDialog();break;case 'nutrition-meals':savedMealsDialog();break;
case 'food-favorite':update(s=>s.foodFavorites=s.foodFavorites.includes(id)?s.foodFavorites.filter(x=>x!==id):[...s.foodFavorites,id],false);foodLibraryDialog();break;
case 'meal-save':{const items=state.foodLogs.filter(x=>x.date===b.dataset.date&&x.meal===b.dataset.meal);if(!items.length)return toast('There are no food entries to save.','error');let name=prompt('Name this saved meal',b.dataset.meal+' favorite');if(!name?.trim())break;update(s=>s.savedMeals.push({id:uid(),name:name.trim(),items:items.map(x=>({foodId:x.foodId,amount:x.amount,unit:x.unit,snapshot:x.snapshot||null}))}));toast('Meal saved for quick reuse.');break}
case 'saved-meal-delete':if(!confirm('Remove saved meal template? Already logged food remains.'))break;update(s=>s.savedMeals=s.savedMeals.filter(x=>x.id!==id));savedMealsDialog();break;
case 'saved-meal-use':{let meal=byId(id,state.savedMeals);if(!meal)break;const m=prompt('Which meal? (Breakfast, Lunch, Dinner, Snack)','Lunch');if(!m)break;let mealName=['Breakfast','Lunch','Dinner','Snack'].find(x=>x.toLowerCase()===m.trim().toLowerCase());if(!mealName)return toast('Choose Breakfast, Lunch, Dinner or Snack.','error');update(s=>meal.items.forEach(x=>s.foodLogs.push({id:uid(),date:view.nutritionDate||day(),meal:mealName,...structuredClone(x)})));closeModal();toast('Saved meal logged.');break}
case 'cardio-add':cardioDialog();break;case 'cardio-view':cardioDetail(id);break;case 'cardio-edit':cardioDialog(id);break;case 'cardio-delete':if(!confirm('Delete this cardio record?'))break;update(s=>s.cardioSessions=s.cardioSessions.filter(x=>x.id!==id));closeModal();break;
case 'cardio-start':{if(state.activeCardio)return;let type=$('#live-cardio-type')?.value||'Running',gps=$('#live-cardio-gps')?.checked||false;update(s=>s.activeCardio={id:uid(),type,createdAt:now(),startedAt:now(),pausedAt:null,pauseMs:0,distanceKm:0,route:[],gpsEnabled:gps,lastPoint:null});if(gps)startGPS();break}
case 'cardio-pause':update(s=>s.activeCardio.pausedAt=now());stopGPS();break;
case 'cardio-resume':update(s=>{let c=s.activeCardio;c.pauseMs+=Date.now()-new Date(c.pausedAt).getTime();c.pausedAt=null;c.lastPoint=null});if(state.activeCardio.gpsEnabled)startGPS();break;
case 'cardio-stop':{let c=state.activeCardio;if(!c)return;let elapsed=Math.max(1,Math.round((Date.now()-new Date(c.startedAt).getTime()-num(c.pauseMs)-(c.pausedAt?Date.now()-new Date(c.pausedAt).getTime():0))/1000));let dist=c.distanceKm;if(!c.gpsEnabled||dist<.01){let answer=prompt('Distance covered in km? Enter 0 if unknown.',f(dist,2));if(answer===null)break;dist=Number(answer);if(!Number.isFinite(dist)||dist<0)return toast('Enter a valid nonnegative distance.','error')}stopGPS();update(s=>{s.cardioSessions.push({id:c.id,type:c.type,mode:'live',createdAt:c.createdAt,date:day(c.startedAt),finishedAt:now(),durationSec:elapsed,distanceKm:round(dist,3),route:c.route,notes:''});s.activeCardio=null});toast('Cardio session saved.');break}
case 'cardio-discard':if(!confirm('Discard live cardio session?'))break;stopGPS();update(s=>s.activeCardio=null);break;
case 'sleep-quick':sleepDialog(false);break;case 'sleep-detailed':sleepDialog(true);break;case 'sleep-edit':sleepDialog(false,id);break;case 'sleep-delete':if(!confirm('Delete this sleep record?'))break;update(s=>s.sleepRecords=s.sleepRecords.filter(x=>x.id!==id));break;
case 'backup-export':exportBackup();break;case 'backup-import':$('#import-file')?.click();break;case 'csv-all':csvDialog();break;case 'csv-type':downloadCSV(b.dataset.type);break;case 'backup-help':backupHelp();break;
default:console.warn('No handler',a)} }
function saveSession(form,quiet=false){let d=formData(form),p=byId(d.programId,state.programs);if(!p)return null;let ss=p.sessions.find(x=>x.id===d.sessionId);let name=String(d.name||'').trim();if(!name){if(!quiet)toast('Enter a session name.','error');return null}if(ss){let rows=ss.exercises.map(x=>{let a=parseNum(d['count-'+x.uid]),b=parseNum(d['reps-'+x.uid]),c=parseNum(d['rest-'+x.uid]);return {...x,sets:clamp(a??x.sets,1,12),reps:clamp(b??x.reps,1,300),rest:clamp(c??x.rest,0,600)}});update(s=>{let target=byId(p.id,s.programs).sessions.find(x=>x.id===ss.id);Object.assign(target,{name:name.slice(0,90),weekday:num(d.weekday),exercises:rows})},false)}else{ss={id:uid(),name:name.slice(0,90),weekday:num(d.weekday),exercises:[]};update(s=>byId(p.id,s.programs).sessions.push(ss),false)}if(!quiet){closeModal();render();toast('Session saved.')}return {programId:p.id,sessionId:ss.id}}
function onSubmit(ev){const form=ev.target.closest('form[data-form]');if(!form)return;ev.preventDefault();const d=formData(form),type=form.dataset.form;function requiredNumber(key,min=0,max=Infinity){let val=parseNum(d[key]);if(val===null||val<min||val>max)throw new Error(`Enter a valid ${key} (${min}–${max===Infinity?'any':max}).`);return val}try{switch(type){
case 'program-generate':{let days=requiredNumber('days',1,7),duration=requiredNumber('duration',15,180),p=generateProgram(days,duration,d.environment,d.experience);update(s=>{s.programs.push(p);if(!s.settings.selectedProgramId){s.settings.selectedProgramId=p.id;s.settings.pointer=0}});view.programId=p.id;closeModal();render();toast('Program generated. Review the sessions before starting.');break}
case 'program-save':{let name=String(d.name||'').trim();if(!name)throw new Error('Program name is required.');if(d.id){update(s=>Object.assign(byId(d.id,s.programs),{name:name.slice(0,90),description:String(d.description||''),environment:d.environment}))}else{let p={id:uid(),name:name.slice(0,90),description:String(d.description||''),environment:d.environment,createdAt:now(),sessions:[]};update(s=>{s.programs.push(p);if(!s.settings.selectedProgramId)s.settings.selectedProgramId=p.id});view.programId=p.id}closeModal();render();break}
case 'session-save':saveSession(form);break;
case 'exercise-save':{let name=String(d.name||'').trim();if(!name)throw new Error('Exercise name required.');const x={id:d.id||uid(),name:name.slice(0,90),primary:d.primary,secondary:String(d.secondary||''),equipment:d.equipment,kind:d.kind,track:d.track,difficulty:d.difficulty,instructions:String(d.instructions||''),custom:true};update(s=>{if(d.id)Object.assign(byId(d.id,s.exercises),x);else s.exercises.push(x)});closeModal();render();toast('Custom exercise saved.');break}
case 'body-save':{const r={id:d.id||uid(),date:d.date};let supplied=0;['weight','bodyFat','chest','waist','arms','shoulders','hips','thighs'].forEach(k=>{if(d[k]!==''&&d[k]!=null){let v=Number(d[k]);if(!Number.isFinite(v)||v<0||v>(k==='bodyFat'?100:500))throw new Error(`Invalid ${k} measurement.`);r[k]=v;supplied++}});if(!supplied)throw new Error('Enter at least one measurement.');update(s=>{if(d.id)Object.assign(byId(d.id,s.bodyRecords),r);else s.bodyRecords.push(r)});closeModal();render();toast('Measurement saved.');break}
case 'goal-save':{let v=requiredNumber('target',.01,1000000);if(!String(d.name||'').trim())throw new Error('Give your goal a name.');update(s=>s.goals.push({id:uid(),name:d.name.trim().slice(0,90),metric:d.metric,exerciseId:d.exerciseId,target:v}));closeModal();render();break}
case 'nutrition-save':{let amount=requiredNumber('amount',.1,100000),item=food(d.foodId);if(!allFoods().some(x=>x.id===d.foodId))throw new Error('Select a food.');if(d.unit!==item.unit&&d.unit!=='serving')throw new Error('Use '+item.unit+' or serving(s) for this food.');let row={id:d.id||uid(),date:d.date,meal:d.meal,foodId:d.foodId,amount,unit:d.unit,snapshot:{name:item.name,kcal:item.kcal,protein:item.protein,fat:item.fat,carbs:item.carbs,unit:item.unit,serving:item.serving}};update(s=>{if(d.id)Object.assign(byId(d.id,s.foodLogs),row);else s.foodLogs.push(row)});view.nutritionDate=d.date;closeModal();render();toast('Food added to meal log.');break}
case 'food-save':{let foodItem={id:d.id||uid(),name:String(d.name||'').trim().slice(0,100),unit:d.unit,serving:requiredNumber('serving',.1,100000),kcal:requiredNumber('kcal',0,10000),protein:requiredNumber('protein',0,1000),carbs:requiredNumber('carbs',0,1000),fat:requiredNumber('fat',0,1000),approx:false,custom:true};if(!foodItem.name)throw new Error('Food name required.');update(s=>{if(d.id)Object.assign(byId(d.id,s.foodsCustom),foodItem);else s.foodsCustom.push(foodItem)});foodLibraryDialog();toast('Custom food saved.');break}
case 'nutrition-target-save':{let calories=requiredNumber('calories',1,20000),protein=requiredNumber('protein',1,1000);update(s=>s.settings.targets={calories,protein});closeModal();render();break}
case 'cardio-save':{let minutes=requiredNumber('minutes',.1,100000),distanceKm=requiredNumber('distanceKm',0,100000);let old=byId(d.id,state.cardioSessions);let v={id:d.id||uid(),date:d.date,type:d.type,distanceKm,durationSec:Math.round(minutes*60),notes:String(d.notes||'').slice(0,2000),createdAt:old?.createdAt||new Date(d.date+'T12:00:00').toISOString(),finishedAt:old?.finishedAt||new Date(d.date+'T12:00:00').toISOString(),mode:old?.mode||'manual',route:old?.route||[]};update(s=>{if(d.id)Object.assign(byId(d.id,s.cardioSessions),v);else s.cardioSessions.push(v)});closeModal();render();toast('Cardio session saved.');break}
case 'sleep-save':{let hours;if(d.mode==='detailed'){let b=d.bedtime.split(':').map(Number),w=d.wakeup.split(':').map(Number),mins=(w[0]*60+w[1])-(b[0]*60+b[1]);if(mins<=0)mins+=1440;hours=round(mins/60,2)}else hours=requiredNumber('durationHours',.1,24);let record={id:d.id||uid(),date:d.date,durationHours:hours,quality:requiredNumber('quality',1,5),bedtime:d.mode==='detailed'?d.bedtime:'',wakeup:d.mode==='detailed'?d.wakeup:'',awakenings:d.mode==='detailed'?num(d.awakenings):0,naps:d.mode==='detailed'?num(d.naps):0,notes:d.mode==='detailed'?String(d.notes||''):''};update(s=>{if(d.id)Object.assign(byId(d.id,s.sleepRecords),record);else s.sleepRecords.push(record)});closeModal();render();toast('Sleep saved.');break}
case 'settings':{let days=requiredNumber('days',1,7),rest=requiredNumber('restSeconds',0,600);update(s=>{Object.assign(s.settings,{days,restSeconds:rest,experience:d.experience,environment:d.environment,scheduleMode:d.scheduleMode})});toast('Preferences saved.');break}
}}catch(err){toast(err.message||'Unable to save entry.','error')}}
function onInput(ev){const el=ev.target;if(el.id==='picker-search'){const q=el.value.trim().toLowerCase();$$('.picker-result').forEach(x=>x.classList.toggle('hide',!x.dataset.label.includes(q)));return}if(el.id==='food-select-search'){const q=el.value.trim().toLowerCase();$$('#foodId option').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(q));return}if(el.id==='food-list-search'){const q=el.value.trim().toLowerCase();$$('.food-result').forEach(x=>x.classList.toggle('hide',!x.dataset.label.includes(q)));return}if(el.dataset.field&&el.dataset.ex){const x=state.activeWorkout?.exercises.find(x=>x.uid===el.dataset.ex);if(!x)return;let item=el.dataset.set?x.sets.find(s=>s.id===el.dataset.set):x;if(!item)return;const key=el.dataset.field;let val=el.value;if(['reps','weight','durationSec','assisted','restSec','rpe','rir'].includes(key)){if(val!==''){let v=Number(val);if(!Number.isFinite(v)||v<0||v>100000)return;val=v}}item[key]=val;save()}}
function onChange(ev){const el=ev.target;if(el.dataset.equipment){let key=el.dataset.equipment+'Equipment',v=el.value;update(s=>{let arr=s.settings[key];s.settings[key]=el.checked?[...new Set([...arr,v])]:arr.filter(x=>x!==v)},false);return}switch(el.id){case'exercise-search':view.search=el.value;render();break;case'exercise-kind':view.kind=el.value;render();break;case'exercise-equipment':view.equipment=el.value;render();break;case'body-metric':view.bodyMetric=el.value;render();break;case'analytics-exercise':view.exerciseId=el.value;render();break;case'nutrition-date':view.nutritionDate=el.value;render();break}}
/* Backups, CSV export, GPS and startup */
const jsonBlob=(name,text,mime='application/json')=>{let url=URL.createObjectURL(new Blob([text],{type:mime+';charset=utf-8'}));let a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000)};
function exportBackup(){const data={app:'FORGE',schemaVersion:1,exportedAt:now(),data:structuredClone(state)};jsonBlob(`forge-backup-${day()}.json`,JSON.stringify(data,null,2));toast('Complete backup downloaded. Store it outside this browser.')}
const backupArrays=['exercises','favorites','programs','workouts','bodyRecords','goals','foodsCustom','foodFavorites','savedMeals','foodLogs','cardioSessions','sleepRecords'];
function validateBackup(doc){if(!doc||doc.app!=='FORGE'||doc.schemaVersion!==1||!doc.data||typeof doc.data!=='object'||doc.data.schemaVersion!==1)throw new Error('This is not a compatible FORGE v1 backup.');const st=doc.data;for(let key of backupArrays)if(!Array.isArray(st[key]))throw new Error('Missing or invalid section: '+key);if(!st.settings||typeof st.settings!=='object'||!Array.isArray(st.settings.gymEquipment)||!Array.isArray(st.settings.homeEquipment))throw new Error('Backup settings are incomplete.');if(st.activeWorkout!==null&&st.activeWorkout!==undefined&&(!Array.isArray(st.activeWorkout.exercises)||typeof st.activeWorkout.startedAt!=='string'))throw new Error('Invalid active workout.');if(st.activeCardio!==null&&st.activeCardio!==undefined&&!Array.isArray(st.activeCardio.route))throw new Error('Invalid active cardio.');for(let w of st.workouts)if(!Array.isArray(w.exercises)||typeof w.id!=='string')throw new Error('Workout record structure invalid.');if(st.programs.some(p=>!Array.isArray(p.sessions)))throw new Error('Program structure invalid.');for(let [key,arr] of Object.entries(st))if(backupArrays.includes(key)&&arr.length>100000)throw new Error('Backup section too large.');return {...defaultState(),...st,settings:{...defaultState().settings,...st.settings,targets:{...defaultState().settings.targets,...st.settings.targets}}}}
async function handleImport(ev){const file=ev.target.files?.[0];ev.target.value='';if(!file)return;if(file.size>30*1024*1024)return toast('Backup too large (limit 30 MB).','error');try{let raw=await file.text(),doc=JSON.parse(raw),incoming=validateBackup(doc);if(!confirm(`Restore backup from ${dateFmt(doc.exportedAt,{year:'numeric',month:'short',day:'numeric'})}? This REPLACES ALL current app records and settings. Export your current data first if you want to keep it.`))return;stopGPS();state=incoming;save();navigate('home');toast('Backup restored. Check your workout and body history.');if(state.activeCardio?.gpsEnabled&&!state.activeCardio.pausedAt)startGPS()}catch(err){toast('Import failed: '+err.message,'error')}}
function csvEscape(value){if(value==null)return '';let s=String(value);return /[",\n\r]/.test(s)?'"'+s.replaceAll('"','""')+'"':s}
function makeCSV(rows){const keys=[...new Set(rows.flatMap(x=>Object.keys(x)))];if(!keys.length)return 'No records\n';return [keys.join(','),...rows.map(row=>keys.map(k=>csvEscape(row[k])).join(','))].join('\r\n')}
function downloadCSV(kind){let data=[];switch(kind){case 'workouts':data=state.workouts.flatMap(w=>w.exercises.flatMap(x=>x.sets.map(s=>({sessionId:w.id,session:w.name,date:w.finishedAt,durationSec:w.durationSec,exercise:exercise(x.exerciseId).name,type:exercise(x.exerciseId).track,completed:s.complete,skipped:s.skipped,reps:s.reps,weightKg:s.weight,assistanceKg:s.assisted,holdSeconds:s.durationSec,rpe:s.rpe,rir:s.rir,notes:x.notes}))));break;case 'body':data=state.bodyRecords.map(x=>({...x}));break;case 'food':data=state.foodLogs.map(x=>({...x,food:food(x.foodId).name,...foodMacros(x)}));break;case 'cardio':data=state.cardioSessions.map(x=>({date:x.date,type:x.type,durationSec:x.durationSec,distanceKm:x.distanceKm,mode:x.mode,notes:x.notes,routeJSON:JSON.stringify(x.route||[])}));break;case 'sleep':data=state.sleepRecords.map(x=>({...x}));break;case 'programs':data=state.programs.flatMap(p=>p.sessions.flatMap(ss=>ss.exercises.map(x=>({program:p.name,session:ss.name,weekday:ss.weekday,exercise:exercise(x.exerciseId).name,sets:x.sets,reps:x.reps,restSeconds:x.rest}))));break}jsonBlob(`forge-${kind}-${day()}.csv`,makeCSV(data),'text/csv');toast('CSV exported. These files are read-only exports, not backup restores.');closeModal()}
function csvDialog(){showModal(`<h2>Export data to CSV</h2><p class="modal-intro">Choose a category to download. For full restoration, use the JSON backup instead.</p><div class="grid cols-2">${[['workouts','Workout sets'],['body','Body measurements'],['food','Nutrition log'],['cardio','Cardio sessions'],['sleep','Sleep records'],['programs','Training programs']].map(([k,l])=>action('csv-type','↓ '+l,'btn',`data-type="${k}"`)).join('')}</div><div class="modal-actions">${action('close-modal','Close','btn')}</div>`) }
function kmBetween(a,b){const r=6371,rad=Math.PI/180,dlat=(b.lat-a.lat)*rad,dlon=(b.lon-a.lon)*rad;const h=Math.sin(dlat/2)**2+Math.cos(a.lat*rad)*Math.cos(b.lat*rad)*Math.sin(dlon/2)**2;return 2*r*Math.asin(Math.min(1,Math.sqrt(h)))}
function stopGPS(){if(gpsWatch!=null&&navigator.geolocation){navigator.geolocation.clearWatch(gpsWatch);gpsWatch=null}}
function startGPS(){if(!state.activeCardio?.gpsEnabled||state.activeCardio.pausedAt)return;if(!navigator.geolocation){toast('GPS unavailable. The timer will continue; enter distance when finishing.','error');return}if(gpsWatch!=null)stopGPS();gpsWatch=navigator.geolocation.watchPosition(pos=>{let c=state.activeCardio;if(!c||c.pausedAt)return;if(pos.coords.accuracy>80)return;let x={lat:pos.coords.latitude,lon:pos.coords.longitude,t:pos.timestamp,accuracy:pos.coords.accuracy};if(c.lastPoint){let d=kmBetween(c.lastPoint,x),elapsed=(x.t-c.lastPoint.t)/1000;if(d<.005)return;if(elapsed<=0||d/(elapsed/3600)>50)return;c.distanceKm=round(c.distanceKm+d,4)}c.route.push(x);c.lastPoint=x;save();if(screen==='cardio'&&document.visibilityState==='visible')render()},err=>{stopGPS();toast('GPS unavailable: '+err.message+'. Time tracking continues.','error')},{enableHighAccuracy:true,maximumAge:5000,timeout:18000})}
document.addEventListener('click',btnClick);
document.addEventListener('submit',onSubmit);
document.addEventListener('input',onInput);
document.addEventListener('change',onChange);
$('#import-file').addEventListener('change',handleImport);
init();
